const OGDB = [{"id":"0001","n":"3/4 sit-up","bp":"waist","tg":"abs","sm":["hip flexors","lower back"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0001-2gPfomN.gif"},{"id":"0002","n":"45° side bend","bp":"waist","tg":"abs","sm":["obliques"],"st":["Stand with your feet shoulder-width apart and your arms extended straight down by your sides.","Keeping your back straight and your core engaged, slowly bend your torso to one side, lowering your hand towards your knee.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."],"gif":"0002-Hy9D21L.gif"},{"id":"0003","n":"air bike","bp":"waist","tg":"abs","sm":["hip flexors"],"st":["Lie flat on your back with your hands placed behind your head.","Lift your legs off the ground and bend your knees at a 90-degree angle.","Bring your right elbow towards your left knee while simultaneously straightening your right leg.","Return to the starting position and repeat the movement on the opposite side, bringing your left elbow towards your right knee while straightening your left leg.","Continue alternating sides in a pedaling motion for the desired number of repetitions."],"gif":"0003-1ZFqTDN.gif"},{"id":"1512","n":"all fours squad stretch","bp":"upper legs","tg":"quads","sm":["hamstrings","glutes"],"st":["Start on all fours with your hands directly under your shoulders and your knees directly under your hips.","Extend one leg straight back, keeping your knee bent and your foot flexed.","Slowly lower your hips towards the ground, feeling a stretch in your quads.","Hold this position for 20-30 seconds.","Switch legs and repeat the stretch on the other side."],"gif":"1512-qBcKorM.gif"},{"id":"0006","n":"alternate heel touchers","bp":"waist","tg":"abs","sm":["obliques"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Extend your arms straight out to the sides, parallel to the ground.","Engaging your abs, lift your shoulders off the ground and reach your right hand towards your right heel.","Return to the starting position and repeat on the left side, reaching your left hand towards your left heel.","Continue alternating sides for the desired number of repetitions."],"gif":"0006-qaZVsGk.gif"},{"id":"1368","n":"ankle circles","bp":"lower legs","tg":"calves","sm":["ankle stabilizers"],"st":["Sit on the ground with your legs extended in front of you.","Lift one leg off the ground and rotate your ankle in a circular motion.","Perform the desired number of circles in one direction, then switch to the other direction.","Repeat with the other leg."],"gif":"1368-uL9CsKm.gif"},{"id":"3293","n":"archer pull up","bp":"back","tg":"lats","sm":["biceps","forearms"],"st":["Start by hanging from a pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Engage your core and pull your shoulder blades down and back.","As you pull yourself up, bend one arm and bring your elbow towards your side, while keeping the other arm straight.","Continue pulling until your chin is above the bar and your bent arm is fully flexed.","Lower yourself back down with control, straightening the bent arm and repeating the movement on the other side.","Alternate sides with each repetition."],"gif":"3293-72BC5Za.gif"},{"id":"3294","n":"archer push up","bp":"chest","tg":"pectorals","sm":["triceps","shoulders","core"],"st":["Start in a push-up position with your hands slightly wider than shoulder-width apart.","Extend one arm straight out to the side, parallel to the ground.","Lower your body by bending your elbows, keeping your back straight and core engaged.","Push back up to the starting position.","Repeat on the other side, extending the opposite arm out to the side.","Continue alternating sides for the desired number of repetitions."],"gif":"3294-A9qxk2F.gif"},{"id":"2355","n":"arm slingers hanging bent knee legs","bp":"waist","tg":"abs","sm":["shoulders","back"],"st":["Hang from a pull-up bar with your arms fully extended and your knees bent at a 90-degree angle.","Engage your core and lift your knees towards your chest, bringing them as close to your elbows as possible.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"2355-uWpxD4v.gif"},{"id":"2333","n":"arm slingers hanging straight legs","bp":"waist","tg":"abs","sm":["shoulders","back"],"st":["Hang from a pull-up bar with your arms fully extended and your legs straight down.","Engage your core and lift your legs up in front of you until they are parallel to the ground.","Hold for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"2333-PXTIwgu.gif"},{"id":"3214","n":"arms apart circular toe touch (male)","bp":"upper legs","tg":"glutes","sm":["hamstrings","quadriceps","calves"],"st":["Stand with your feet shoulder-width apart and arms extended to the sides.","Keeping your legs straight, bend forward at the waist and reach down towards your toes with your right hand.","As you reach down, simultaneously lift your left leg straight up behind you, maintaining balance.","Return to the starting position and repeat the movement with your left hand reaching towards your toes and your right leg lifting up behind you.","Continue alternating sides for the desired number of repetitions."],"gif":"3214-RtyAsy1.gif"},{"id":"3204","n":"arms overhead full sit-up (male)","bp":"waist","tg":"abs","sm":["hip flexors","lower back"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Extend your arms overhead, keeping them straight.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is upright.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"3204-NAkmgdx.gif"},{"id":"3220","n":"astride jumps (male)","bp":"cardio","tg":"cardiovascular system","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart.","Bend your knees and lower your body into a squat position.","Jump explosively upwards, extending your legs and arms.","While in the air, spread your legs apart and bring your arms out to the sides.","Land softly with your feet shoulder-width apart, bending your knees to absorb the impact.","Repeat for the desired number of repetitions."],"gif":"3220-f9lVSSI.gif"},{"id":"3672","n":"back and forth step","bp":"cardio","tg":"cardiovascular system","sm":["quadriceps","hamstrings","glutes","calves"],"st":["Stand with your feet shoulder-width apart.","Step forward with your right foot, bending your knee and lowering your body into a lunge position.","Push off with your right foot and step back to the starting position.","Repeat the movement with your left foot, alternating legs with each step.","Continue stepping back and forth, maintaining a steady pace.","Repeat for the desired duration or number of repetitions."],"gif":"3672-fNGumX0.gif"},{"id":"3297","n":"back lever","bp":"back","tg":"upper back","sm":["biceps","forearms","core"],"st":["Start by hanging from a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.","Engage your core and pull your shoulder blades down and back.","Bend your knees and tuck them towards your chest.","Slowly lift your legs up, keeping them straight, until your body is parallel to the ground.","Hold this position for a few seconds, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"3297-GaSzzuh.gif"},{"id":"1405","n":"back pec stretch","bp":"back","tg":"lats","sm":["shoulders","chest"],"st":["Stand tall with your feet shoulder-width apart.","Extend your arms straight out in front of you, parallel to the ground.","Cross your arms in front of your body, with your right arm over your left arm.","Interlock your fingers and rotate your palms away from your body.","Slowly raise your arms up and away from your body, feeling a stretch in your back and chest.","Hold the stretch for 15-30 seconds, then release.","Repeat on the opposite side."],"gif":"1405-chfnQnM.gif"},{"id":"1473","n":"backward jump","bp":"upper legs","tg":"quads","sm":["hamstrings","glutes","calves"],"st":["Stand with your feet shoulder-width apart.","Bend your knees slightly and jump backwards, pushing off with both feet.","Land softly on the balls of your feet, bending your knees to absorb the impact.","Repeat for the desired number of repetitions."],"gif":"1473-SaDOwk7.gif"},{"id":"0020","n":"balance board","bp":"upper legs","tg":"quads","sm":["calves","hamstrings","glutes"],"st":["Place the balance board on a flat surface.","Step onto the balance board with one foot, ensuring it is centered.","Slowly shift your weight onto the foot on the balance board, keeping your core engaged.","Maintain your balance and stability as you hold the position for a desired amount of time.","Repeat the exercise with the other foot."],"gif":"0020-xAySMB0.gif"},{"id":"3212","n":"basic toe touch (male)","bp":"upper legs","tg":"glutes","sm":["hamstrings","calves"],"st":["Stand with your feet shoulder-width apart and your arms by your sides.","Bend forward at the waist, keeping your back straight and your knees slightly bent.","Reach down towards your toes with your hands, keeping your legs as straight as possible.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"gif":"3212-BbfB8Gb.gif"},{"id":"3360","n":"bear crawl","bp":"cardio","tg":"cardiovascular system","sm":["core","shoulders","triceps"],"st":["Start on all fours with your hands directly under your shoulders and your knees directly under your hips.","Lift your knees slightly off the ground, keeping your back flat and your core engaged.","Move your right hand and left foot forward simultaneously, followed by your left hand and right foot.","Continue crawling forward, alternating your hand and foot movements.","Maintain a steady pace and keep your core tight throughout the exercise.","Continue for the desired distance or time."],"gif":"3360-0Yz8WdV.gif"},{"id":"0129","n":"bench dip (knees bent)","bp":"upper arms","tg":"triceps","sm":["chest","shoulders"],"st":["Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.","Slide your butt off the bench and straighten your legs in front of you, keeping your heels on the ground.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."],"gif":"0129-RrLske5.gif"},{"id":"1399","n":"bench dip on floor","bp":"upper arms","tg":"triceps","sm":["chest","shoulders"],"st":["Sit on the edge of a bench or chair with your hands gripping the edge, fingers pointing forward.","Slide your butt off the bench, supporting your weight with your hands.","Lower your body by bending your elbows until your upper arms are parallel to the floor.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"gif":"1399-9RT8oQW.gif"},{"id":"0130","n":"bench hip extension","bp":"upper legs","tg":"glutes","sm":["hamstrings"],"st":["Sit on a bench with your back against the bench and your feet flat on the ground.","Place your hands on the bench for support.","Engage your glutes and hamstrings, then lift your hips off the bench until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0130-u27Kcdz.gif"},{"id":"3019","n":"bench pull-ups","bp":"back","tg":"lats","sm":["biceps","forearms"],"st":["Position yourself under a bar or a sturdy horizontal surface that is at chest height.","Grab the bar or surface with an overhand grip, slightly wider than shoulder-width apart.","Hang with your arms fully extended and your body straight.","Pull your chest towards the bar or surface by squeezing your shoulder blades together and bending your elbows.","Continue pulling until your chin is above the bar or surface.","Lower yourself back down to the starting position with control.","Repeat for the desired number of repetitions."],"gif":"3019-mExgrF9.gif"},{"id":"3639","n":"bent knee lying twist (male)","bp":"upper legs","tg":"glutes","sm":["obliques","hip flexors"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Extend your arms out to the sides, perpendicular to your body.","Keeping your knees together, slowly lower them to one side, aiming to touch the ground with your knees.","Pause for a moment, then engage your core and slowly lift your knees back to the starting position.","Repeat the movement to the other side.","Continue alternating sides for the desired number of repetitions."],"gif":"3639-6sYyrRX.gif"},{"id":"1770","n":"biceps leg concentration curl","bp":"upper arms","tg":"biceps","sm":["forearms"],"st":["Sit on a bench with your legs spread apart and your feet flat on the ground.","Hold a dumbbell in one hand and place your elbow on the inside of your thigh, just above the knee.","With your palm facing up, curl the dumbbell towards your shoulder while keeping your upper arm stationary.","Squeeze your biceps at the top of the movement, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"gif":"1770-sJFIDIp.gif"},{"id":"0139","n":"biceps narrow pull-ups","bp":"upper arms","tg":"biceps","sm":["forearms","shoulders"],"st":["Hang from a pull-up bar with your palms facing towards you and your hands shoulder-width apart.","Engage your core and pull yourself up towards the bar, focusing on using your biceps to lift your body.","Pause for a moment at the top, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0139-50BETrz.gif"},{"id":"0140","n":"biceps pull-up","bp":"upper arms","tg":"biceps","sm":["forearms","shoulders"],"st":["Hang from a pull-up bar with your palms facing away from you and your hands shoulder-width apart.","Engage your core and pull yourself up by bending your elbows, bringing your chest towards the bar.","Pause at the top of the movement, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0140-guT8YnS.gif"},{"id":"0137","n":"body-up","bp":"upper arms","tg":"triceps","sm":["chest","shoulders"],"st":["Start by placing your hands on a raised surface, such as a bench or parallel bars, with your palms facing down and fingers pointing forward.","Extend your legs out in front of you, keeping your heels on the ground and your body straight.","Lower your body by bending your elbows, keeping them close to your sides, until your upper arms are parallel to the ground.","Pause for a moment, then push through your palms to straighten your arms and lift your body back up to the starting position.","Repeat for the desired number of repetitions."],"gif":"0137-U6G2gk9.gif"},{"id":"3543","n":"bodyweight drop jump squat","bp":"upper legs","tg":"glutes","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart.","Lower your body into a squat position by bending your knees and pushing your hips back.","Jump up explosively, extending your hips, knees, and ankles.","While in mid-air, quickly bring your feet together.","Land softly on the balls of your feet and immediately drop back into a squat position.","Repeat for the desired number of repetitions."],"gif":"3543-wfotm7S.gif"},{"id":"3544","n":"bodyweight incline side plank","bp":"waist","tg":"abs","sm":["obliques","shoulders"],"st":["Start by lying on your side with your legs extended and stacked on top of each other.","Place your forearm on the ground directly below your shoulder, with your elbow bent at a 90-degree angle.","Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.","Hold this position for the desired amount of time.","Lower your hips back down to the ground and repeat on the other side."],"gif":"3544-5VXmnV5.gif"},{"id":"1771","n":"bodyweight kneeling triceps extension","bp":"upper arms","tg":"triceps","sm":["shoulders","chest"],"st":["Kneel down on the ground with your knees hip-width apart.","Place your hands on the ground in front of you, shoulder-width apart, fingers pointing forward.","Extend your legs straight behind you, balancing on your toes and hands, forming a straight line from head to heels.","Bend your elbows and lower your upper body towards the ground, keeping your elbows close to your sides.","Pause for a moment at the bottom, then push through your hands to straighten your arms and return to the starting position.","Repeat for the desired number of repetitions."],"gif":"1771-s0HKO2I.gif"},{"id":"1769","n":"bodyweight side lying biceps curl","bp":"upper arms","tg":"biceps","sm":["forearms"],"st":["Lie on your side with your legs extended and your head supported by your arm.","Hold your upper arm against your side and bend your elbow to curl your forearm towards your shoulder.","Pause for a moment at the top, then slowly lower your forearm back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"1769-gscGLOU.gif"},{"id":"3168","n":"bodyweight squatting row","bp":"back","tg":"upper back","sm":["biceps","shoulders"],"st":["Stand with your feet shoulder-width apart, holding onto a sturdy object or suspension trainer with your arms extended.","Lower your body into a squat position, keeping your back straight and your knees behind your toes.","From the squat position, pull your body up towards the object or suspension trainer, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"3168-3xK09Sk.gif"},{"id":"3167","n":"bodyweight squatting row (with towel)","bp":"back","tg":"upper back","sm":["biceps","shoulders"],"st":["Stand with your feet shoulder-width apart, holding a towel in front of you with your palms facing down.","Bend your knees and lower your body into a squat position, keeping your back straight and your chest up.","As you lower into the squat, simultaneously pull the towel towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the squat, then slowly return to the starting position while extending your arms.","Repeat for the desired number of repetitions."],"gif":"3167-BReCuOn.gif"},{"id":"1373","n":"bodyweight standing calf raise","bp":"lower legs","tg":"calves","sm":["ankles","feet"],"st":["Stand with your feet shoulder-width apart, toes pointing forward.","Place your hands on a wall or stable surface for balance.","Slowly raise your heels off the ground, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"1373-bJYHBIN.gif"},{"id":"3156","n":"bodyweight standing close-grip one arm row","bp":"back","tg":"upper back","sm":["biceps","forearms"],"st":["Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in one hand with a neutral grip.","Bend forward at the hips, keeping your back straight and your core engaged.","Pull the dumbbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"gif":"3156-v2DfH14.gif"},{"id":"3158","n":"bodyweight standing close-grip row","bp":"back","tg":"upper back","sm":["biceps","forearms"],"st":["Stand with your feet shoulder-width apart and knees slightly bent.","Bend forward at the waist, keeping your back straight and your core engaged.","Extend your arms straight in front of you, gripping the bar or handles with a close grip.","Pull the bar or handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release and return to the starting position.","Repeat for the desired number of repetitions."],"gif":"3158-tig3PXb.gif"},{"id":"3162","n":"bodyweight standing one arm row","bp":"back","tg":"upper back","sm":["biceps","forearms"],"st":["Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in one hand.","Bend forward at the hips, keeping your back straight and your core engaged.","Let the dumbbell hang straight down in front of you, with your arm fully extended.","Pull the dumbbell up towards your chest, keeping your elbow close to your body.","Squeeze your shoulder blades together at the top of the movement.","Lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"gif":"3162-xbkPfaw.gif"},{"id":"3161","n":"bodyweight standing one arm row (with towel)","bp":"back","tg":"upper back","sm":["biceps","forearms"],"st":["Stand with your feet shoulder-width apart, knees slightly bent, and hold a towel with one hand.","Bend forward at the hips, keeping your back straight and your core engaged.","Pull the towel towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the towel back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"gif":"3161-O4oIqQD.gif"},{"id":"3166","n":"bodyweight standing row","bp":"back","tg":"upper back","sm":["biceps","shoulders"],"st":["Stand with your feet shoulder-width apart and knees slightly bent.","Grasp a bar or handles with an overhand grip, palms facing down.","Keep your back straight and core engaged.","Pull the bar or handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the top of the movement.","Slowly release and extend your arms back to the starting position.","Repeat for the desired number of repetitions."],"gif":"3166-wd4ds3s.gif"},{"id":"3165","n":"bodyweight standing row (with towel)","bp":"back","tg":"upper back","sm":["biceps","shoulders"],"st":["Stand with your feet shoulder-width apart and hold a towel in front of you with both hands.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Pull the towel towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."],"gif":"3165-uTv34oq.gif"},{"id":"0138","n":"bottoms-up","bp":"waist","tg":"abs","sm":["obliques","hip flexors"],"st":["Lie flat on your back with your legs extended and your arms by your sides.","Bend your knees and bring them towards your chest, keeping your feet off the ground.","Engaging your abs, lift your hips off the ground, bringing your knees towards your head.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0138-CI6baTY.gif"},{"id":"1374","n":"box jump down with one leg stabilization","bp":"lower legs","tg":"calves","sm":["quadriceps","hamstrings","glutes"],"st":["Stand in front of a box or platform with your feet shoulder-width apart.","Bend your knees and jump onto the box, landing softly with one foot on the box and the other foot hanging off the edge.","Stabilize yourself on the box with the foot that is on it, while keeping the other foot off the ground.","Hold this position for a few seconds, engaging your calf muscles to maintain balance.","Slowly step down with the foot that is on the box, returning to the starting position.","Repeat the exercise with the other leg."],"gif":"1374-iPm26QU.gif"},{"id":"2466","n":"bridge - mountain climber (cross body)","bp":"waist","tg":"abs","sm":["glutes","quadriceps","hamstrings","shoulders","triceps"],"st":["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Engage your core and lift your right foot off the ground, bringing your right knee towards your left elbow.","Return your right foot to the starting position and repeat the movement with your left foot towards your right elbow.","Continue alternating sides, moving at a controlled pace.","Keep your hips level and avoid lifting your hips too high or sagging them too low.","Maintain a steady breathing pattern throughout the exercise.","Repeat for the desired number of repetitions."],"gif":"2466-9c6T1YX.gif"},{"id":"1160","n":"burpee","bp":"cardio","tg":"cardiovascular system","sm":["quadriceps","hamstrings","calves","shoulders","chest"],"st":["Start in a standing position with your feet shoulder-width apart.","Lower your body into a squat position by bending your knees and placing your hands on the floor in front of you.","Kick your feet back into a push-up position.","Perform a push-up, keeping your body in a straight line.","Jump your feet back into the squat position.","Jump up explosively, reaching your arms overhead.","Land softly and immediately lower back into a squat position to begin the next repetition."],"gif":"1160-dK9394r.gif"},{"id":"0870","n":"butt-ups","bp":"waist","tg":"abs","sm":["hip flexors","lower back"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands by your sides, palms facing down.","Engaging your abs, lift your legs off the ground, bringing your knees towards your chest.","At the top of the movement, squeeze your abs and pause for a moment.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0870-qcNN2FN.gif"},{"id":"1494","n":"butterfly yoga pose","bp":"upper legs","tg":"adductors","sm":["hamstrings","groin"],"st":["Sit on the floor with your legs extended in front of you.","Bend your knees and bring the soles of your feet together, allowing your knees to fall out to the sides.","Hold onto your ankles or feet with your hands.","Sit up tall and lengthen your spine.","Gently press your knees down towards the floor, feeling a stretch in your inner thighs.","Hold this position for a few breaths.","To release, slowly bring your knees back up and extend your legs."],"gif":"1494-bWlZvXh.gif"},{"id":"1407","n":"calf push stretch with hands against wall","bp":"lower legs","tg":"calves","sm":["hamstrings"],"st":["Stand facing a wall with your feet hip-width apart.","Place your hands against the wall at shoulder height.","Step back with one foot, keeping your heel on the ground and your leg straight.","Bend your front knee slightly and lean forward, feeling a stretch in your calf.","Hold the stretch for 20-30 seconds.","Switch legs and repeat the stretch."],"gif":"1407-PzNxakt.gif"},{"id":"1377","n":"calf stretch with hands against wall","bp":"lower legs","tg":"calves","sm":["hamstrings"],"st":["Stand facing a wall with your feet hip-width apart.","Place your hands against the wall at shoulder height.","Step your right foot back, keeping your heel on the ground and your leg straight.","Bend your left knee and lean forward, keeping your back leg straight and your heel on the ground.","Hold the stretch for 20-30 seconds.","Switch legs and repeat the stretch."],"gif":"1377-m0tCHqc.gif"},{"id":"2963","n":"captains chair straight leg raise","bp":"waist","tg":"abs","sm":["hip flexors"],"st":["Sit on the captain's chair with your back against the backrest and your forearms resting on the arm pads.","Keep your upper body stable and your back straight.","Engage your abs and lift your legs up in front of you, keeping them straight.","Continue lifting until your legs are parallel to the ground or as high as you can comfortably go.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"2963-weoDEpH.gif"},{"id":"1548","n":"chair leg extended stretch","bp":"upper legs","tg":"quads","sm":["hamstrings","calves"],"st":["Sit on the edge of a chair with your back straight and feet flat on the ground.","Extend one leg straight out in front of you, keeping your heel on the ground.","Lean forward slightly, feeling a stretch in your quadriceps.","Hold this position for 20-30 seconds.","Switch legs and repeat the stretch."],"gif":"1548-xGgAGPm.gif"},{"id":"1271","n":"chest and front of shoulder stretch","bp":"chest","tg":"pectorals","sm":["deltoids"],"st":["Stand tall with your feet shoulder-width apart.","Extend your arms straight out in front of you at shoulder height.","Cross your arms in front of your body, with your right arm on top of your left arm.","Interlace your fingers and press your palms together.","Gently squeeze your shoulder blades together and push your hands forward, feeling a stretch in your chest and front of your shoulders.","Hold the stretch for 20-30 seconds, then release.","Repeat for the desired number of repetitions."],"gif":"1271-Uto7l43.gif"},{"id":"0251","n":"chest dip","bp":"chest","tg":"pectorals","sm":["triceps","shoulders"],"st":["Position yourself on parallel bars with your arms fully extended and your body straight.","Lower your body by bending your elbows until your shoulders are below your elbows.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"gif":"0251-9WTm7dq.gif"},{"id":"1430","n":"chest dip (on dip-pull-up cage)","bp":"chest","tg":"pectorals","sm":["triceps","shoulders"],"st":["Adjust the dip bars to a height that allows you to comfortably grip them.","Stand between the bars and place your hands on each bar, slightly wider than shoulder-width apart.","Jump up and straighten your arms, supporting your body weight on the bars.","Bend your knees and cross your ankles behind you.","Lower your body by bending your elbows, keeping your chest up and your shoulders down.","Continue lowering until your shoulders are below your elbows or until you feel a stretch in your chest.","Push through your palms and extend your elbows to raise your body back up to the starting position.","Repeat for the desired number of repetitions."],"gif":"1430-XgWyAiA.gif"},{"id":"2462","n":"chest dip on straight bar","bp":"chest","tg":"pectorals","sm":["triceps","shoulders"],"st":["Grab the parallel bars with your palms facing down and your arms fully extended.","Bend your knees and cross your ankles.","Lower your body by bending your arms until your shoulders are below your elbows.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"gif":"2462-LQFOrMn.gif"},{"id":"3216","n":"chest tap push-up (male)","bp":"chest","tg":"pectorals","sm":["triceps","shoulders"],"st":["Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","As you lower yourself, tap your chest with your right hand.","Push yourself back up to the starting position.","Repeat the movement, this time tapping your chest with your left hand.","Continue alternating sides for the desired number of repetitions."],"gif":"3216-7E06s6d.gif"},{"id":"1326","n":"chin-up","bp":"back","tg":"lats","sm":["biceps","forearms"],"st":["Hang from a pull-up bar with your palms facing towards you and your hands shoulder-width apart.","Engage your core and pull your body up towards the bar, leading with your chest.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"1326-T2mxWqc.gif"},{"id":"0253","n":"chin-ups (narrow parallel grip)","bp":"back","tg":"upper back","sm":["biceps","forearms"],"st":["Hang from a pull-up bar with a narrow parallel grip, palms facing towards you.","Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0253-G70mEAJ.gif"},{"id":"0257","n":"circles knee stretch","bp":"lower legs","tg":"calves","sm":["hamstrings","quadriceps"],"st":["Stand with your feet shoulder-width apart and your hands on your hips.","Bend your knees slightly and lift your heels off the ground, balancing on the balls of your feet.","Keeping your knees bent, rotate your knees in a circular motion, first clockwise and then counterclockwise.","Perform the movement for the desired number of repetitions."],"gif":"0257-X7jbxra.gif"},{"id":"1273","n":"clap push up","bp":"chest","tg":"pectorals","sm":["triceps","shoulders"],"st":["Start in a high plank position with your hands slightly wider than shoulder-width apart.","Lower your body towards the ground by bending your elbows, keeping your core engaged.","Push through your palms explosively to propel your body off the ground.","While in mid-air, clap your hands together before landing back in the starting position.","Repeat for the desired number of repetitions."],"gif":"1273-wigSg76.gif"},{"id":"0258","n":"clock push-up","bp":"chest","tg":"pectorals","sm":["triceps","shoulders","core"],"st":["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","As you lower, rotate your body to the left, extending your left arm straight out to the side.","Push back up to the starting position, while rotating your body to the center.","Repeat the push-up, this time rotating your body to the right and extending your right arm out to the side.","Continue alternating sides with each repetition."],"gif":"0258-CMAxnsG.gif"},{"id":"1327","n":"close grip chin-up","bp":"back","tg":"lats","sm":["biceps","forearms"],"st":["Grab the pull-up bar with your palms facing towards you and your hands shoulder-width apart.","Hang from the bar with your arms fully extended and your feet off the ground.","Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"1327-VnfUNW7.gif"},{"id":"0259","n":"close-grip push-up","bp":"upper arms","tg":"triceps","sm":["chest","shoulders"],"st":["Start in a high plank position with your hands placed close together, directly under your shoulders.","Engage your core and lower your body towards the ground, keeping your elbows close to your sides.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."],"gif":"0259-x6KpKpq.gif"},{"id":"2398","n":"close-grip push-up (on knees)","bp":"upper arms","tg":"triceps","sm":["chest","shoulders"],"st":["Start by getting on your hands and knees, with your hands shoulder-width apart and your knees hip-width apart.","Lower your upper body towards the ground by bending your elbows, keeping them close to your sides.","Pause for a moment when your chest is just above the ground.","Push through your palms to straighten your arms and return to the starting position.","Repeat for the desired number of repetitions."],"gif":"2398-v3vLFW0.gif"},{"id":"0260","n":"cocoons","bp":"waist","tg":"abs","sm":["hip flexors","lower back"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0260-SLKj2pX.gif"},{"id":"1468","n":"crab twist toe touch","bp":"waist","tg":"abs","sm":["obliques","hip flexors"],"st":["Start by sitting on the ground with your knees bent and feet flat on the floor.","Place your hands behind you, fingers pointing towards your feet, and lift your hips off the ground.","Extend one leg straight out in front of you while simultaneously reaching your opposite hand towards your toes.","Return to the starting position and repeat on the other side.","Continue alternating sides for the desired number of repetitions."],"gif":"1468-xgsGFVM.gif"},{"id":"0262","n":"cross body crunch","bp":"waist","tg":"abs","sm":["obliques"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, lift your upper body off the ground and twist to bring your right elbow towards your left knee.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat on the other side, bringing your left elbow towards your right knee.","Repeat for the desired number of repetitions."],"gif":"0262-rbu5UUb.gif"},{"id":"0267","n":"crunch (hands overhead)","bp":"waist","tg":"abs","sm":["hip flexors"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Extend your arms straight above your head.","Engaging your abs, lift your upper body off the ground, curling forward towards your knees.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0267-kjJ3VoQ.gif"},{"id":"0274","n":"crunch floor","bp":"waist","tg":"abs","sm":["hip flexors"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engage your abs and lift your shoulders off the ground, curling forward towards your knees.","Pause for a moment at the top, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0274-TFqbd8t.gif"},{"id":"3016","n":"curl-up","bp":"waist","tg":"abs","sm":["hip flexors"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"3016-g2oKspu.gif"},{"id":"3769","n":"curtsey squat","bp":"upper legs","tg":"glutes","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart.","Take a step diagonally behind and across your body with your right foot, crossing it behind your left leg.","Bend both knees as if you were curtsying, lowering your body towards the ground.","Keep your torso upright and your weight on your front foot.","Push through your front foot to return to the starting position.","Repeat on the other side, stepping diagonally behind and across your body with your left foot."],"gif":"3769-gUjqdei.gif"},{"id":"0276","n":"dead bug","bp":"waist","tg":"abs","sm":["hip flexors","lower back"],"st":["Lie flat on your back with your arms extended towards the ceiling.","Bend your knees and lift your legs off the ground, creating a 90-degree angle at your hips and knees.","Engage your core and lower back to press your lower back into the ground.","Slowly lower your right arm and left leg towards the ground, keeping them straight and hovering just above the floor.","Pause for a moment, then return to the starting position.","Repeat the movement with your left arm and right leg.","Continue alternating sides for the desired number of repetitions."],"gif":"0276-iny3m5y.gif"},{"id":"0277","n":"decline crunch","bp":"waist","tg":"abs","sm":["hip flexors"],"st":["Lie on a decline bench with your feet secured and your knees bent at a 90-degree angle.","Place your hands behind your head or across your chest.","Engage your abs and lift your upper body towards your knees, curling your torso.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0277-9Ap7miY.gif"},{"id":"0279","n":"decline push-up","bp":"chest","tg":"pectorals","sm":["triceps","shoulders"],"st":["Place your hands on the ground slightly wider than shoulder-width apart, with your feet elevated on a stable surface.","Keep your body in a straight line from head to toe, engaging your core muscles.","Lower your chest towards the ground by bending your elbows, keeping them close to your body.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."],"gif":"0279-i5cEhka.gif"},{"id":"0282","n":"decline sit-up","bp":"waist","tg":"abs","sm":["hip flexors","lower back"],"st":["Lie on a decline bench with your feet secured and your knees bent.","Place your hands behind your head or across your chest.","Engage your abs and lift your upper body off the bench, curling forward towards your knees.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0282-QLL2gdc.gif"},{"id":"0283","n":"diamond push-up","bp":"upper arms","tg":"triceps","sm":["chest","shoulders"],"st":["Start in a high plank position with your hands close together, forming a diamond shape with your thumbs and index fingers.","Keep your body in a straight line from head to toe, engaging your core and glutes.","Lower your chest towards the diamond shape formed by your hands, keeping your elbows close to your body.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."],"gif":"0283-soIB2rj.gif"},{"id":"0284","n":"donkey calf raise","bp":"lower legs","tg":"calves","sm":["hamstrings","glutes"],"st":["Stand with your toes on an elevated surface, such as a step or block.","Place your hands on a stable support, such as a wall or railing, for balance.","Raise your heels as high as possible, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0284-u5ESqzH.gif"},{"id":"1275","n":"drop push up","bp":"chest","tg":"pectorals","sm":["triceps","shoulders"],"st":["Start in a high plank position with your hands slightly wider than shoulder-width apart.","Lower your chest towards the ground, keeping your elbows close to your body.","Once your chest is just above the ground, quickly drop your knees to the ground.","Push yourself back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."],"gif":"1275-Q497lAE.gif"},{"id":"1167","n":"dynamic chest stretch (male)","bp":"chest","tg":"pectorals","sm":["shoulders","triceps"],"st":["Stand tall with your feet shoulder-width apart.","Extend your arms straight out to the sides, parallel to the ground.","Slowly bring your arms forward, crossing them in front of your body.","Feel the stretch in your chest muscles.","Hold the stretch for 10-30 seconds.","Return to the starting position and repeat for the desired number of repetitions."],"gif":"1167-3uj0Ozg.gif"},{"id":"3287","n":"elbow dips","bp":"upper arms","tg":"triceps","sm":["chest","shoulders"],"st":["Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.","Slide your hips forward off the bench and straighten your legs, keeping your heels on the ground.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Pause for a moment at the bottom, then push through your hands to straighten your arms and lift your body back up to the starting position.","Repeat for the desired number of repetitions."],"gif":"3287-LkoAWAE.gif"},{"id":"1772","n":"elbow lift - reverse push-up","bp":"back","tg":"upper back","sm":["triceps","shoulders"],"st":["Start by lying face down on the ground with your legs extended and your hands placed directly under your shoulders.","Engage your core and press through your palms to lift your upper body off the ground, keeping your elbows close to your sides.","Pause at the top for a moment, squeezing your upper back muscles.","Slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"1772-wbUYILZ.gif"},{"id":"0443","n":"elbow-to-knee","bp":"waist","tg":"abs","sm":["obliques"],"st":["Start by lying flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engage your abs and lift your upper body off the ground, bringing your right elbow towards your left knee.","At the same time, bring your left knee towards your right elbow, creating a twisting motion.","Pause for a moment at the top, then slowly lower your upper body and extend your legs back to the starting position.","Repeat the movement, this time bringing your left elbow towards your right knee and your right knee towards your left elbow.","Continue alternating sides for the desired number of repetitions."],"gif":"0443-jvp6DiD.gif"},{"id":"3292","n":"elevator","bp":"back","tg":"upper back","sm":["shoulders","trapezius"],"st":["Stand with your feet shoulder-width apart and your knees slightly bent.","Place your hands on your hips or cross them in front of your chest.","Keeping your back straight, slowly bend forward at the waist, lowering your upper body towards the ground.","Pause for a moment at the bottom, then slowly raise your upper body back up to the starting position.","Repeat for the desired number of repetitions."],"gif":"3292-zYmNaoY.gif"},{"id":"3303","n":"flag","bp":"waist","tg":"abs","sm":["obliques","shoulders"],"st":["Start by gripping a vertical pole with both hands, palms facing each other, and arms fully extended.","Engage your core and lift your legs off the ground, keeping them straight.","Using your core and upper body strength, raise your legs until they are parallel to the ground.","Hold this position for as long as you can, maintaining a straight body line.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"3303-pQ0Mx1Z.gif"},{"id":"0456","n":"flexion leg sit up (bent knee)","bp":"waist","tg":"abs","sm":["hip flexors"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","At the same time, lift your legs off the ground, bending your knees and bringing them towards your chest.","Pause for a moment at the top, then slowly lower your upper body and legs back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0456-AR0ig3o.gif"},{"id":"0457","n":"flexion leg sit up (straight arm)","bp":"waist","tg":"abs","sm":["hip flexors","quadriceps"],"st":["Lie flat on your back with your legs extended and arms straight above your head.","Engaging your abs, lift your upper body off the ground while simultaneously lifting your legs towards your chest.","Reach your hands towards your toes as you lift your upper body and legs.","Pause for a moment at the top, then slowly lower your upper body and legs back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0457-KZn52RC.gif"},{"id":"0459","n":"flutter kicks","bp":"upper legs","tg":"glutes","sm":["hip flexors","lower abs"],"st":["Lie flat on your back with your legs extended and your hands by your sides.","Engage your core and lift your legs off the ground about 6 inches.","Keeping your legs straight, alternate lifting one leg slightly higher than the other.","Continue this fluttering motion for the desired number of repetitions."],"gif":"0459-UVo2Qs2.gif"},{"id":"1472","n":"forward jump","bp":"upper legs","tg":"quads","sm":["calves","hamstrings","glutes"],"st":["Stand with your feet shoulder-width apart.","Bend your knees and lower your body into a squat position.","Swing your arms back for momentum.","Jump forward explosively, extending your hips, knees, and ankles.","Land softly on the balls of your feet and immediately go into the next jump.","Repeat for the desired number of repetitions."],"gif":"1472-uZKq7lo.gif"},{"id":"3470","n":"forward lunge (male)","bp":"upper legs","tg":"glutes","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet hip-width apart and hands on your hips.","Take a big step forward with your right foot, lowering your body into a lunge position.","Bend your right knee to about 90 degrees, keeping your knee aligned with your ankle.","Push off with your right foot and return to the starting position.","Repeat with your left leg, alternating sides for the desired number of repetitions."],"gif":"3470-kMzUs9Y.gif"},{"id":"2429","n":"frog crunch","bp":"waist","tg":"abs","sm":["hip flexors"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"2429-FFRP97T.gif"},{"id":"3301","n":"frog planche","bp":"waist","tg":"abs","sm":["shoulders","chest","triceps"],"st":["Start in a push-up position with your hands shoulder-width apart and your feet together.","Bend your elbows and lower your body towards the ground, keeping your back straight.","As you lower your body, lift your feet off the ground and bring your knees towards your chest.","Hold this position for a few seconds, then extend your legs back out and push yourself back up to the starting position.","Repeat for the desired number of repetitions."],"gif":"3301-rQhGcin.gif"},{"id":"3296","n":"front lever","bp":"waist","tg":"abs","sm":["lats","shoulders","forearms"],"st":["Start by hanging from a pull-up bar with an overhand grip, hands shoulder-width apart.","Engage your core and pull your shoulder blades down and back.","Bend your knees and tuck them towards your chest.","Simultaneously, lift your legs up and extend them straight out in front of you, keeping your body parallel to the ground.","Hold this position for as long as you can, aiming for a full front lever position.","To release, slowly lower your legs back down and return to the starting position.","Repeat for the desired number of repetitions."],"gif":"3296-PkCN2lv.gif"},{"id":"3295","n":"front lever reps","bp":"back","tg":"upper back","sm":["core","shoulders"],"st":["Hang from a pull-up bar with an overhand grip, palms facing away from you.","Engage your core and pull your shoulder blades down and back.","Keeping your body straight, lift your legs up until they are parallel to the ground.","Hold this position for as long as you can, aiming for 10-20 seconds.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"3295-hbY9wqG.gif"},{"id":"0464","n":"front plank with twist","bp":"waist","tg":"abs","sm":["obliques","shoulders"],"st":["Start in a high plank position with your hands directly under your shoulders and your body in a straight line from head to toe.","Engage your core and glutes to maintain a stable position.","Rotate your torso to the right, lifting your right arm and extending it towards the ceiling.","Keep your hips and legs stable as you twist.","Hold for a moment, then return to the starting position.","Repeat the twist on the left side.","Continue alternating sides for the desired number of repetitions."],"gif":"0464-CosupLu.gif"},{"id":"3315","n":"full maltese","bp":"waist","tg":"abs","sm":["shoulders","chest"],"st":["Start by standing with your feet shoulder-width apart and your arms extended straight out to the sides.","Slowly lean forward, keeping your arms straight, until your upper body is parallel to the ground.","Engage your core and hold this position for a few seconds.","Return to the starting position by pushing through your feet and standing back up.","Repeat for the desired number of repetitions."],"gif":"3315-YRaCa5Y.gif"},{"id":"3299","n":"full planche","bp":"waist","tg":"abs","sm":["shoulders","chest","triceps"],"st":["Start in a push-up position with your hands shoulder-width apart and your fingers pointing forward.","Engage your core and slowly shift your weight forward, lifting your feet off the ground.","Continue shifting your weight forward until your body is parallel to the ground, balancing on your hands.","Hold this position for as long as you can, maintaining a straight body line.","Slowly lower your feet back to the ground and return to the starting position.","Repeat for the desired number of repetitions."],"gif":"3299-YZ4961r.gif"},{"id":"3327","n":"full planche push-up","bp":"chest","tg":"pectorals","sm":["shoulders","triceps","core"],"st":["Start in a push-up position with your hands placed slightly wider than shoulder-width apart.","Engage your core and lower your body down towards the ground, keeping your elbows close to your sides.","As you lower yourself, lean your body forward and lift your feet off the ground, balancing on your hands.","Continue to lower your body until your chest is just above the ground.","Push through your hands and extend your arms to lift your body back up to the starting position.","Maintain a straight line from your head to your heels throughout the movement.","Repeat for the desired number of repetitions."],"gif":"3327-gw9PqGk.gif"},{"id":"0466","n":"gironda sternum chin","bp":"back","tg":"lats","sm":["biceps","rhomboids","rear deltoids"],"st":["Stand facing a high bar with your feet shoulder-width apart.","Reach up and grab the bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your lats and biceps to pull your chest up towards the bar, leading with your sternum.","Pause for a moment at the top, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0466-IL0JUxR.gif"},{"id":"3561","n":"glute bridge march","bp":"upper legs","tg":"glutes","sm":["hamstrings","quadriceps"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.","While keeping your hips lifted, lift one foot off the ground and bring your knee towards your chest.","Lower your foot back to the ground and repeat the movement with the other leg.","Continue alternating legs in a marching motion while maintaining the bridge position.","Repeat for the desired number of repetitions."],"gif":"3561-GibBPPg.gif"},{"id":"3523","n":"glute bridge two legs on bench (male)","bp":"upper legs","tg":"glutes","sm":["hamstrings","core"],"st":["Sit on the edge of a bench with your back against it and your feet flat on the ground.","Place your hands on the bench beside your hips for support.","Engage your glutes and hamstrings, then lift your hips off the bench until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"3523-aWedzZX.gif"},{"id":"3193","n":"glute-ham raise","bp":"upper legs","tg":"hamstrings","sm":["glutes","lower back"],"st":["Adjust the glute-ham raise machine to fit your body.","Position yourself face down on the machine with your ankles secured.","Place your hands on your chest or cross them over your chest.","Engage your hamstrings and glutes to lift your upper body up towards the ceiling.","Continue lifting until your body is in a straight line from your head to your heels.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"3193-Vvwjz6N.gif"},{"id":"0467","n":"gorilla chin","bp":"waist","tg":"abs","sm":["forearms","biceps"],"st":["Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp a pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your palms facing away from you.","Engage your core and pull your body up towards the bar, bringing your chin above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0467-bmwlYvD.gif"},{"id":"0469","n":"groin crunch","bp":"waist","tg":"abs","sm":["hip flexors","inner thighs"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, lift your legs off the ground, bringing your knees towards your chest.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0469-mWppALS.gif"},{"id":"3221","n":"half knee bends (male)","bp":"cardio","tg":"cardiovascular system","sm":["quadriceps","hamstrings","glutes"],"st":["Stand with your feet shoulder-width apart.","Bend your knees and lower your body down as if you were sitting back into a chair.","Keep your chest up and your weight in your heels.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"gif":"3221-ia6kIIl.gif"},{"id":"3202","n":"half sit-up (male)","bp":"waist","tg":"abs","sm":["hip flexors"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"3202-iQ241UP.gif"},{"id":"1511","n":"hamstring stretch","bp":"upper legs","tg":"hamstrings","sm":["glutes"],"st":["Stand with your feet shoulder-width apart.","Step forward with your right foot and shift your weight onto your right leg.","Keeping your back straight, slowly bend forward at the hips, reaching towards your right foot with both hands.","Hold the stretch for 20-30 seconds, then return to the starting position.","Repeat on the other side."],"gif":"1511-99rWm7w.gif"},{"id":"3218","n":"hands clasped circular toe touch (male)","bp":"upper legs","tg":"glutes","sm":["hamstrings","quadriceps","calves"],"st":["Stand with your feet shoulder-width apart and your hands clasped together in front of your chest.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Lower your hands towards your toes in a circular motion, reaching as far as you can without straining.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"gif":"3218-B5xca8s.gif"},{"id":"3215","n":"hands reversed clasped circular toe touch (male)","bp":"upper legs","tg":"glutes","sm":["hamstrings","quadriceps","calves"],"st":["Stand with your feet shoulder-width apart and your arms extended to the sides.","Bend forward at the waist, keeping your back straight and your knees slightly bent.","Reach down with your hands and clasp them together behind your legs.","Slowly raise your hands up and over your head in a circular motion, keeping your legs straight.","Continue the circular motion until your hands touch your toes.","Reverse the motion and bring your hands back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"3215-yq3GAJX.gif"},{"id":"3302","n":"handstand","bp":"upper arms","tg":"triceps","sm":["shoulders","core"],"st":["Find an open space with enough room to perform a handstand.","Place your hands on the ground shoulder-width apart, fingers pointing forward.","Kick your legs up towards the wall, using your core and shoulders to maintain balance.","Once in a handstand position, engage your triceps to support your body weight.","Hold the handstand for as long as you can maintain balance.","To come down, slowly lower your legs back to the ground.","Repeat for the desired number of repetitions."],"gif":"3302-XooAdhl.gif"},{"id":"0471","n":"handstand push-up","bp":"upper arms","tg":"triceps","sm":["shoulders","chest","core"],"st":["Find a wall and face away from it, standing a few feet away.","Place your hands on the ground shoulder-width apart and kick your feet up against the wall, coming into a handstand position.","Bend your elbows and lower your head towards the ground, keeping your body in a straight line.","Push through your hands and extend your arms to return to the starting position.","Repeat for the desired number of repetitions."],"gif":"0471-rQxwMxO.gif"},{"id":"1764","n":"hanging leg hip raise","bp":"waist","tg":"abs","sm":["hip flexors","lower back"],"st":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up by flexing your hips and knees until your thighs are parallel to the ground.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"1764-VEcJRo2.gif"},{"id":"0472","n":"hanging leg raise","bp":"waist","tg":"abs","sm":["hip flexors"],"st":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up in front of you, keeping them straight.","Continue lifting until your legs are parallel to the ground or as high as you can comfortably go.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0472-I3tsCnC.gif"},{"id":"1761","n":"hanging oblique knee raise","bp":"waist","tg":"abs","sm":["obliques"],"st":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your knees towards your chest, twisting your torso to the side as you do so.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat on the other side, twisting your torso in the opposite direction.","Continue alternating sides for the desired number of repetitions."],"gif":"1761-BaE7O6U.gif"},{"id":"0473","n":"hanging pike","bp":"waist","tg":"abs","sm":["hip flexors","shoulders"],"st":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up towards the bar, keeping them straight.","Continue lifting until your body forms a 'V' shape, with your legs parallel to the ground.","Hold the position for a moment, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0473-nuBF9MO.gif"},{"id":"0474","n":"hanging straight leg hip raise","bp":"waist","tg":"abs","sm":["hip flexors"],"st":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up in front of you until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0474-pj0X0tF.gif"},{"id":"0475","n":"hanging straight leg raise","bp":"waist","tg":"abs","sm":["hip flexors"],"st":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up in front of you, keeping them straight.","Continue lifting until your legs are parallel to the ground or as high as you can comfortably go.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0475-4Ml7QFO.gif"},{"id":"0476","n":"hanging straight twisting leg hip raise","bp":"waist","tg":"abs","sm":["obliques","hip flexors"],"st":["Hang from a pull-up bar with your arms fully extended and your legs straight.","Engage your core and lift your legs up towards your chest, keeping them straight.","Once your legs are parallel to the ground, twist your hips to one side, bringing your legs towards that side.","Pause for a moment, then return to the starting position.","Repeat the movement, but this time twist your hips to the opposite side.","Continue alternating sides for the desired number of repetitions."],"gif":"0476-Q6bvyen.gif"},{"id":"3636","n":"high knee against wall","bp":"cardio","tg":"cardiovascular system","sm":["quadriceps","hamstrings","glutes","calves"],"st":["Stand facing a wall with your feet hip-width apart.","Place your hands on the wall for support.","Engage your core and lift your right knee up towards your chest, while keeping your left foot on the ground.","Quickly switch legs, bringing your left knee up towards your chest and lowering your right foot back down.","Continue alternating legs in a running motion, bringing your knees up as high as possible.","Maintain a fast pace and keep your upper body stable throughout the exercise.","Repeat for the desired duration or number of repetitions."],"gif":"3636-ealLwvX.gif"},{"id":"0484","n":"hip raise (bent knee)","bp":"waist","tg":"abs","sm":["glutes","hamstrings"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands by your sides, palms facing down.","Engage your core and glutes, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0484-196HJGw.gif"},{"id":"1418","n":"hug keens to chest","bp":"upper legs","tg":"glutes","sm":["hamstrings","quadriceps"],"st":["Start by standing with your feet shoulder-width apart.","Bend your knees and lower your body down into a squat position.","As you squat down, bring your knees up towards your chest and hug them with your arms.","Hold this position for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"gif":"1418-znP9SIh.gif"},{"id":"0489","n":"hyperextension","bp":"back","tg":"spine","sm":["glutes","hamstrings"],"st":["Adjust the hyperextension bench so that your upper thighs are resting on the pad and your feet are secured.","Cross your arms over your chest or place your hands behind your head.","Lower your upper body towards the ground while keeping your back straight.","Pause for a moment at the bottom, then raise your upper body back up until it is in line with your legs.","Repeat for the desired number of repetitions."],"gif":"0489-zhMwOwE.gif"},{"id":"0488","n":"hyperextension (on bench)","bp":"back","tg":"spine","sm":["glutes","hamstrings"],"st":["Adjust the hyperextension bench so that your hips are resting comfortably on the pad and your feet are secured.","Cross your arms over your chest or place your hands behind your head.","Slowly lower your upper body towards the ground while keeping your back straight.","Pause for a moment at the bottom, then raise your upper body back up until it is in line with your legs.","Repeat for the desired number of repetitions."],"gif":"0488-zkgRrbK.gif"},{"id":"3289","n":"impossible dips","bp":"upper arms","tg":"triceps","sm":["chest","shoulders"],"st":["Position yourself between two parallel bars with your arms fully extended and your body suspended in the air.","Bend your knees and cross your ankles.","Lower your body by bending your elbows until your upper arms are parallel to the ground.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"gif":"3289-05Cf2v8.gif"},{"id":"1471","n":"inchworm","bp":"waist","tg":"abs","sm":["shoulders","hamstrings"],"st":["Start in a standing position with your feet hip-width apart.","Bend forward at the waist and place your hands on the ground in front of you.","Walk your hands forward until you are in a high plank position, with your body in a straight line from head to toe.","Pause for a moment, then walk your hands back towards your feet, keeping your legs as straight as possible.","Once your hands reach your feet, stand back up to the starting position.","Repeat for the desired number of repetitions."],"gif":"1471-ZgsNQ6d.gif"},{"id":"3698","n":"inchworm v. 2","bp":"waist","tg":"abs","sm":["shoulders","hamstrings"],"st":["Start in a standing position with your feet hip-width apart.","Bend forward at the waist and place your hands on the ground in front of you.","Walk your hands forward until you are in a high plank position, with your body in a straight line from head to toe.","Keeping your legs straight, walk your feet towards your hands, bringing your hips up towards the ceiling.","Continue walking your hands forward, repeating the movement for the desired number of repetitions."],"gif":"3698-TV87DNB.gif"},{"id":"0490","n":"incline close-grip push-up","bp":"upper arms","tg":"triceps","sm":["chest","shoulders"],"st":["Place your hands on an elevated surface, such as a bench or step, slightly wider than shoulder-width apart.","Extend your legs behind you, resting on the balls of your feet, with your body forming a straight line from head to heels.","Lower your chest towards the elevated surface by bending your elbows, keeping them close to your sides.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"gif":"0490-1YB40kg.gif"},{"id":"0491","n":"incline leg hip raise (leg straight)","bp":"waist","tg":"abs","sm":["hip flexors"],"st":["Lie on an incline bench with your back flat against the bench and your legs extended straight out in front of you.","Place your hands on the sides of the bench for support.","Engaging your abs, lift your legs off the bench, raising them as high as you can while keeping them straight.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0491-eVxAzgz.gif"},{"id":"0492","n":"incline push up depth jump","bp":"chest","tg":"pectorals","sm":["triceps","shoulders","core"],"st":["Find an elevated surface, such as a bench or step, and place your hands shoulder-width apart on the edge.","Step your feet back, keeping your body in a straight line from head to heels.","Lower your chest towards the edge of the surface, bending your elbows and keeping your body aligned.","Push through your palms to extend your arms and return to the starting position.","Jump off the edge of the surface, landing softly with your knees slightly bent.","Repeat the push-up and depth jump for the desired number of repetitions."],"gif":"0492-CB8WET1.gif"},{"id":"0493","n":"incline push-up","bp":"chest","tg":"pectorals","sm":["triceps","shoulders"],"st":["Place your hands on an elevated surface, such as a bench or step, slightly wider than shoulder-width apart.","Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.","Lower your chest towards the elevated surface by bending your elbows, keeping your body in a straight line.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"gif":"0493-B1EVP9F.gif"},{"id":"3785","n":"incline push-up (on box)","bp":"chest","tg":"pectorals","sm":["triceps","shoulders"],"st":["Place your hands on the edge of a box or elevated surface, slightly wider than shoulder-width apart.","Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.","Lower your chest towards the box by bending your elbows, keeping your body in a straight line.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"gif":"3785-F7vjXqT.gif"},{"id":"0494","n":"incline reverse grip push-up","bp":"chest","tg":"pectorals","sm":["triceps","shoulders"],"st":["Place your hands on the edge of a bench or elevated surface, slightly wider than shoulder-width apart.","Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.","Lower your chest towards the bench by bending your elbows, keeping them close to your sides.","Pause for a moment at the bottom, then push yourself back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."],"gif":"0494-XaaRnRn.gif"},{"id":"3011","n":"incline scapula push up","bp":"chest","tg":"serratus anterior","sm":["triceps","shoulders"],"st":["Set up an incline bench at a 45-degree angle.","Place your hands on the bench slightly wider than shoulder-width apart.","Position your feet on the ground, hip-width apart.","Lower your chest towards the bench, keeping your elbows tucked in.","As you lower, retract your shoulder blades, squeezing your scapulae together.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."],"gif":"3011-GdMa1ET.gif"},{"id":"0495","n":"incline twisting sit-up","bp":"waist","tg":"abs","sm":["obliques"],"st":["Set up an incline bench at a 45-degree angle.","Lie down on the bench with your feet secured under the foot pads.","Place your hands behind your head or across your chest.","Engage your abs and lift your upper body off the bench, curling forward.","As you curl up, twist your torso to one side, bringing your elbow towards the opposite knee.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat the movement, this time twisting your torso to the other side.","Continue alternating sides for the desired number of repetitions."],"gif":"0495-9ZGZuOD.gif"},{"id":"0496","n":"inverse leg curl (bench support)","bp":"upper legs","tg":"hamstrings","sm":["glutes","calves"],"st":["Lie face down on a bench with your hips at the edge and your legs extended straight behind you.","Hold onto the bench for support.","Keeping your upper body still, bend your knees and curl your legs towards your glutes.","Pause for a moment at the top, then slowly extend your legs back to the starting position.","Repeat for the desired number of repetitions."],"gif":"0496-ms7tjSG.gif"},{"id":"2400","n":"inverse leg curl (on pull-up cable machine)","bp":"upper legs","tg":"hamstrings","sm":["glutes","calves"],"st":["Adjust the cable machine so that the ankle straps are at the lowest setting.","Lie face down on the bench with your legs extended and the ankle straps attached to your feet.","Hold onto the handles of the bench for stability.","Bend your knees and curl your legs towards your glutes, squeezing your hamstrings.","Pause for a moment at the top of the movement, then slowly lower your legs back to the starting position.","Repeat for the desired number of repetitions."],"gif":"2400-0rHfvy9.gif"},{"id":"0499","n":"inverted row","bp":"back","tg":"upper back","sm":["biceps","forearms"],"st":["Set up a bar at waist height or use a suspension trainer.","Stand facing the bar or suspension trainer, with your feet shoulder-width apart.","Grab the bar or handles with an overhand grip, slightly wider than shoulder-width apart.","Lean back, keeping your body straight and your heels on the ground.","Pull your chest towards the bar or handles, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower yourself back to the starting position.","Repeat for the desired number of repetitions."],"gif":"0499-bZGHsAZ.gif"},{"id":"2300","n":"inverted row bent knees","bp":"back","tg":"upper back","sm":["biceps","forearms"],"st":["Set up a bar at waist height and lie underneath it.","Grab the bar with an overhand grip, slightly wider than shoulder-width apart.","Position your body so that your heels are on the ground and your body is straight.","Pull your chest up towards the bar by squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"2300-VPPtusI.gif"},{"id":"2298","n":"inverted row on bench","bp":"back","tg":"upper back","sm":["biceps","forearms"],"st":["Set up a bench at a height that allows your body to hang freely underneath it.","Lie face up on the ground with your head towards the bench.","Reach up and grab the bench with an overhand grip, slightly wider than shoulder-width apart.","Position your body so that your heels are on the ground and your arms are fully extended.","Engage your core and squeeze your shoulder blades together as you pull your chest up towards the bench.","Pause for a moment at the top of the movement, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"2298-Mxa7Cr8.gif"},{"id":"0497","n":"inverted row v. 2","bp":"back","tg":"upper back","sm":["biceps","forearms"],"st":["Set up a bar at waist height on a Smith machine or use a suspension trainer.","Stand facing the bar or suspension trainer and grab it with an overhand grip, hands shoulder-width apart.","Walk your feet forward, leaning back until your body is at a slight angle.","Keep your body straight and pull your chest up towards the bar or handles, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0497-uX3sUBz.gif"},{"id":"0498","n":"inverted row with straps","bp":"back","tg":"upper back","sm":["biceps","forearms"],"st":["Set up a suspension trainer or straps at chest height.","Stand facing the anchor point and grab the handles with an overhand grip.","Walk your feet forward, leaning back until your body is at an angle.","Keep your body straight and engage your core.","Pull your chest towards the handles, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower yourself back to the starting position.","Repeat for the desired number of repetitions."],"gif":"0498-jdiExfW.gif"},{"id":"1419","n":"iron cross stretch","bp":"upper legs","tg":"glutes","sm":["hamstrings","quadriceps"],"st":["Lie flat on your back with your arms extended out to the sides.","Raise your legs up towards the ceiling, keeping them straight.","Slowly lower your legs to one side, aiming to touch the floor with your feet.","Hold the stretch for a few seconds, then return your legs to the starting position.","Repeat the stretch on the other side.","Continue alternating sides for the desired number of repetitions."],"gif":"1419-pZwUsKB.gif"},{"id":"1297","n":"isometric chest squeeze","bp":"chest","tg":"pectorals","sm":["triceps","shoulders"],"st":["Stand with your feet shoulder-width apart and your knees slightly bent.","Extend your arms straight out in front of you, parallel to the ground, with your palms facing each other.","Squeeze your chest muscles together as hard as you can, while keeping your arms straight.","Hold this position for a few seconds, focusing on contracting your chest muscles.","Release the squeeze and relax your chest muscles.","Repeat for the desired number of repetitions."],"gif":"1297-HbSG1Pw.gif"},{"id":"0500","n":"isometric wipers","bp":"chest","tg":"pectorals","sm":["shoulders","triceps","core"],"st":["Start by lying flat on your back on a mat or bench.","Extend your arms straight out to the sides, perpendicular to your body.","Engage your core and lift both legs off the ground, keeping them together and straight.","Slowly lower your legs to one side, aiming to touch the ground with your feet while maintaining control.","Pause for a moment, then use your core to lift your legs back to the starting position.","Repeat the movement, this time lowering your legs to the opposite side.","Continue alternating sides for the desired number of repetitions."],"gif":"0500-11wrviz.gif"},{"id":"0501","n":"jack burpee","bp":"cardio","tg":"cardiovascular system","sm":["quadriceps","hamstrings","calves","shoulders","triceps","core"],"st":["Start in a standing position with your feet shoulder-width apart.","Lower your body into a squat position, placing your hands on the ground in front of you.","Kick your feet back, landing in a push-up position.","Perform a push-up, lowering your chest to the ground and then pushing back up.","Jump your feet forward, landing in a squat position.","Jump up explosively, reaching your arms overhead.","Land softly and immediately lower back into the squat position to begin the next repetition."],"gif":"0501-mr7pkqP.gif"},{"id":"3224","n":"jack jump (male)","bp":"cardio","tg":"cardiovascular system","sm":["quadriceps","calves"],"st":["Stand with your feet together and your arms by your sides.","Jump up, spreading your feet apart and raising your arms above your head.","As you land, quickly jump back to the starting position.","Repeat for the desired number of repetitions."],"gif":"3224-1g5bPpA.gif"},{"id":"0507","n":"jackknife sit-up","bp":"waist","tg":"abs","sm":["hip flexors"],"st":["Lie flat on your back with your legs extended and your arms overhead.","Engage your core and lift your legs and upper body simultaneously, reaching your hands towards your toes.","Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0507-mbkgB44.gif"},{"id":"0508","n":"janda sit-up","bp":"waist","tg":"abs","sm":["hip flexors","lower back"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0508-1GPHRyK.gif"},{"id":"0514","n":"jump squat","bp":"upper legs","tg":"glutes","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart.","Lower your body into a squat position by bending your knees and pushing your hips back.","Jump explosively off the ground, extending your hips, knees, and ankles.","While in mid-air, quickly bring your arms forward for balance.","Land softly on the balls of your feet and immediately go into the next repetition.","Repeat for the desired number of repetitions."],"gif":"0514-LIlE5Tn.gif"},{"id":"0513","n":"jump squat v. 2","bp":"upper legs","tg":"glutes","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart.","Lower your body into a squat position by bending your knees and pushing your hips back.","Jump explosively, extending your hips and knees fully.","Land softly on the balls of your feet and immediately lower your body back into a squat position.","Repeat for the desired number of repetitions."],"gif":"0513-TDYiji6.gif"},{"id":"0555","n":"kick out sit","bp":"upper legs","tg":"hamstrings","sm":["quadriceps","glutes"],"st":["Sit on the edge of a bench or chair with your feet flat on the ground and your knees bent at a 90-degree angle.","Lean back slightly and place your hands on the edge of the bench or chair for support.","Engaging your hamstrings, lift your feet off the ground and extend your legs straight out in front of you.","Pause for a moment at the top, then slowly bend your knees and bring your feet back towards your body.","Repeat for the desired number of repetitions."],"gif":"0555-v7p5bYl.gif"},{"id":"0558","n":"kipping muscle up","bp":"back","tg":"lats","sm":["biceps","triceps","shoulders","core"],"st":["Start by hanging from a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.","Engage your core and use a swinging motion to generate momentum.","As you swing forward, pull your chest towards the bar, using your lats and biceps to initiate the movement.","Continue the upward motion until your chest reaches the bar, then transition into a dip position by pushing down on the bar and extending your arms.","Lower yourself back down to the starting position by bending your arms and controlling the descent.","Repeat for the desired number of repetitions."],"gif":"0558-pM07UxU.gif"},{"id":"3640","n":"knee touch crunch","bp":"waist","tg":"abs","sm":["hip flexors"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, lift your shoulder blades off the ground and reach your right hand towards your left knee.","Return to the starting position and repeat, this time reaching your left hand towards your right knee.","Continue alternating sides for the desired number of repetitions."],"gif":"3640-dTg95eZ.gif"},{"id":"1346","n":"kneeling lat stretch","bp":"back","tg":"lats","sm":["shoulders","triceps"],"st":["Kneel on the ground with your knees hip-width apart and your toes pointing back.","Extend your arms overhead and interlace your fingers.","Keeping your back straight, slowly lean to the right side, feeling a stretch in your left lat muscle.","Hold the stretch for 20-30 seconds, then return to the starting position.","Repeat the stretch on the left side, leaning to the left and feeling a stretch in your right lat muscle.","Continue alternating sides for the desired number of repetitions."],"gif":"1346-f38OEuO.gif"},{"id":"3239","n":"kneeling plank tap shoulder (male)","bp":"waist","tg":"abs","sm":["shoulders","triceps"],"st":["Start in a kneeling position with your hands on the ground, shoulder-width apart.","Extend your legs behind you, resting on your toes, and lift your body into a plank position.","Keeping your core engaged and your hips stable, lift one hand off the ground and tap the opposite shoulder.","Return the hand to the ground and repeat with the other hand.","Continue alternating sides for the desired number of repetitions."],"gif":"3239-h1ezqSu.gif"},{"id":"3211","n":"kneeling push-up (male)","bp":"chest","tg":"pectorals","sm":["triceps","shoulders"],"st":["Start by kneeling on the ground with your hands shoulder-width apart, fingers pointing forward.","Extend your legs behind you, resting on the balls of your feet, so that your body forms a straight line from head to heels.","Engage your core and lower your body towards the ground by bending your elbows, keeping them close to your sides.","Continue lowering until your chest is just above the ground, then push back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"gif":"3211-ZOuKWir.gif"},{"id":"3288","n":"korean dips","bp":"chest","tg":"pectorals","sm":["triceps","shoulders"],"st":["Position yourself between two parallel bars with your arms extended and supporting your body weight.","Lower your body by bending your elbows until your upper arms are parallel to the ground.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"gif":"3288-rWoBmi5.gif"},{"id":"3418","n":"l-pull-up","bp":"back","tg":"lats","sm":["biceps","forearms"],"st":["Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Hang with your arms fully extended and your body straight.","Engage your lats and biceps to pull your body up towards the bar, keeping your elbows close to your body.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"3418-d1GgzTU.gif"},{"id":"3419","n":"l-sit on floor","bp":"waist","tg":"abs","sm":["hip flexors"],"st":["Sit on the floor with your legs extended in front of you.","Place your hands on the floor beside your hips, fingers pointing forward.","Engage your core and lift your legs off the ground, keeping them straight.","Try to bring your legs parallel to the floor, forming an 'L' shape with your body.","Hold this position for as long as you can.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"3419-UpWmA5E.gif"},{"id":"3300","n":"lean planche","bp":"waist","tg":"abs","sm":["shoulders","chest","triceps"],"st":["Start in a push-up position with your hands shoulder-width apart and your body straight.","Engage your core and slowly shift your weight forward, bringing your shoulders past your hands.","Keep your elbows slightly bent and your body straight as you lean forward.","Hold this position for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"gif":"3300-LYJodFS.gif"},{"id":"2271","n":"left hook. boxing","bp":"shoulders","tg":"delts","sm":["biceps","triceps","forearms"],"st":["Stand with your feet shoulder-width apart and your knees slightly bent.","Keep your left hand up to protect your face and your right hand by your chin.","Rotate your hips and pivot on your left foot as you extend your left arm forward in a punching motion.","Twist your torso and engage your core muscles to generate power in the punch.","Snap your arm back to the starting position and repeat for the desired number of repetitions."],"gif":"2271-hoXt6wv.gif"},{"id":"0570","n":"leg pull in flat bench","bp":"waist","tg":"abs","sm":["hip flexors","lower back"],"st":["Sit on a flat bench with your legs extended straight out in front of you.","Place your hands on the bench beside your hips for support.","Engage your abs and lift your legs off the ground, bringing your knees towards your chest.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0570-OyoZ3Pu.gif"},{"id":"1576","n":"leg up hamstring stretch","bp":"upper legs","tg":"hamstrings","sm":["glutes"],"st":["Lie flat on your back with your legs extended.","Bend one knee and bring it towards your chest, holding onto your thigh or shin.","Straighten your leg as much as possible while keeping it elevated.","Hold the stretch for 20-30 seconds.","Repeat with the other leg."],"gif":"1576-sU5BrfP.gif"},{"id":"3013","n":"low glute bridge on floor","bp":"upper legs","tg":"glutes","sm":["hamstrings","core"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your arms by your sides, palms facing down.","Engage your glutes and core, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, squeezing your glutes.","Slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"3013-u0cNiij.gif"},{"id":"1352","n":"lower back curl","bp":"back","tg":"spine","sm":["glutes","hamstrings"],"st":["Lie flat on your stomach with your legs extended and your arms by your sides.","Engage your glutes and hamstrings, and slowly lift your upper body off the ground, curling your back upwards.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"1352-ANbbry2.gif"},{"id":"3582","n":"lunge with jump","bp":"upper legs","tg":"glutes","sm":["quadriceps","hamstrings","calves"],"st":["Start by standing with your feet shoulder-width apart.","Take a step forward with your right foot, lowering your body into a lunge position.","Push off with your right foot and jump into the air, switching the position of your feet mid-air.","Land softly with your left foot forward and immediately lower your body into a lunge position.","Continue alternating between lunges and jumps for the desired number of repetitions."],"gif":"3582-PM1PZjg.gif"},{"id":"1688","n":"lunge with twist","bp":"waist","tg":"abs","sm":["quadriceps","glutes","hamstrings"],"st":["Start by standing with your feet shoulder-width apart.","Take a step forward with your right foot, lowering your body into a lunge position.","As you lunge, twist your torso to the right, bringing your left elbow towards your right knee.","Pause for a moment, then return to the starting position.","Repeat on the other side, stepping forward with your left foot and twisting your torso to the left.","Continue alternating sides for the desired number of repetitions."],"gif":"1688-K9VL0Jq.gif"},{"id":"0613","n":"lying (side) quads stretch","bp":"upper legs","tg":"quads","sm":["hamstrings"],"st":["Lie on your side with your legs straight.","Bend your top leg and grab your ankle or foot with your hand.","Gently pull your ankle or foot towards your glutes until you feel a stretch in your quads.","Hold the stretch for 20-30 seconds.","Release the stretch and repeat on the other side."],"gif":"0613-BWnJR72.gif"},{"id":"2312","n":"lying elbow to knee","bp":"waist","tg":"abs","sm":["hip flexors","lower back"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engage your abs and lift your upper body off the ground, bringing your right elbow towards your left knee.","At the same time, extend your right leg straight out and lift it off the ground.","Pause for a moment, then return to the starting position.","Repeat the movement, this time bringing your left elbow towards your right knee and extending your left leg.","Continue alternating sides for the desired number of repetitions."],"gif":"2312-AQIhRjM.gif"},{"id":"0620","n":"lying leg raise flat bench","bp":"waist","tg":"abs","sm":["hip flexors"],"st":["Lie flat on a flat bench with your back pressed against it.","Place your hands under your glutes for support.","Keep your legs straight and together, and lift them up towards the ceiling.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0620-WhuFnR7.gif"},{"id":"0865","n":"lying leg-hip raise","bp":"waist","tg":"abs","sm":["hip flexors"],"st":["Lie flat on your back with your legs extended and your arms by your sides.","Place your hands under your glutes for support.","Engage your core and lift your legs off the ground, raising them towards the ceiling.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0865-9IxJdtC.gif"},{"id":"0624","n":"march sit (wall)","bp":"upper legs","tg":"glutes","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your back against a wall and your feet hip-width apart.","Slowly slide your back down the wall until your knees are bent at a 90-degree angle.","Lift your right foot off the ground and bring your knee towards your chest.","Lower your right foot back down and lift your left foot off the ground, bringing your knee towards your chest.","Continue alternating between lifting your right and left foot for the desired number of repetitions."],"gif":"0624-sVQCCeG.gif"},{"id":"0627","n":"mixed grip chin-up","bp":"back","tg":"lats","sm":["biceps","forearms"],"st":["Grab the pull-up bar with an underhand grip (palms facing towards you) and your hands slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your feet off the ground.","Engage your back muscles and pull your body up towards the bar, leading with your chest.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position with control.","Repeat for the desired number of repetitions."],"gif":"0627-T8UpLkb.gif"},{"id":"3217","n":"modified hindu push-up (male)","bp":"chest","tg":"pectorals","sm":["triceps","shoulders","core"],"st":["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet hip-width apart.","Lower your body towards the ground, bending your elbows and keeping your core engaged.","As you lower your body, shift your weight back and lift your hips up towards the ceiling, creating an inverted V shape with your body.","Continue to lower your body until your chest is just above the ground, then reverse the movement, pushing your hips back down and extending your arms to return to the starting position.","Repeat for the desired number of repetitions."],"gif":"3217-epOSYUZ.gif"},{"id":"1421","n":"modified push up to lower arms","bp":"lower arms","tg":"forearms","sm":["triceps","chest","shoulders"],"st":["Start in a push-up position with your hands directly under your shoulders and your body in a straight line.","Lower your body down towards the ground by bending your elbows, keeping them close to your sides.","Once your elbows are at a 90-degree angle, lower your forearms to the ground, keeping your elbows directly under your shoulders.","Pause for a moment, then push through your palms to lift your forearms back up to the starting position.","Repeat for the desired number of repetitions."],"gif":"1421-arvaszz.gif"},{"id":"0628","n":"monster walk","bp":"upper legs","tg":"glutes","sm":["hamstrings","quadriceps"],"st":["Place a resistance band around your ankles.","Stand with your feet shoulder-width apart and slightly bend your knees.","Take a step to the side with your right foot, maintaining tension on the resistance band.","Follow with your left foot, stepping to the side to return to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"gif":"0628-O95afRA.gif"},{"id":"0630","n":"mountain climber","bp":"cardio","tg":"cardiovascular system","sm":["core","shoulders","triceps"],"st":["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Engage your core and bring your right knee towards your chest, then quickly switch and bring your left knee towards your chest.","Continue alternating legs in a running motion, keeping your hips low and your core engaged.","Maintain a steady pace and breathe evenly throughout the exercise.","Repeat for the desired number of repetitions."],"gif":"0630-RJgzwny.gif"},{"id":"0631","n":"muscle up","bp":"back","tg":"lats","sm":["biceps","triceps","shoulders","chest"],"st":["Start by hanging from a pull-up bar with your palms facing away from you and your arms fully extended.","Engage your core and pull your body up towards the bar, leading with your chest.","As you reach the top of the movement, transition your grip so that your palms are facing towards you.","Continue pulling yourself up until your chest is above the bar and your arms are fully flexed.","Reverse the movement by slowly lowering yourself back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0631-yJUHKTn.gif"},{"id":"1401","n":"muscle-up (on vertical bar)","bp":"back","tg":"lats","sm":["biceps","triceps","forearms"],"st":["Start by hanging from a vertical bar with your palms facing away from you and your arms fully extended.","Engage your core and pull your body up towards the bar, leading with your chest.","As you pull yourself up, lean back slightly and bring your elbows towards your sides.","Continue pulling until your chest reaches the bar and your elbows are fully bent.","Pause for a moment at the top, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"1401-Af0EW2I.gif"},{"id":"1403","n":"neck side stretch","bp":"neck","tg":"levator scapulae","sm":["trapezius","sternocleidomastoid"],"st":["Stand or sit up straight with your shoulders relaxed.","Tilt your head to one side, bringing your ear towards your shoulder.","Hold the stretch for 15-30 seconds.","Repeat on the other side.","Perform 2-4 sets on each side."],"gif":"1403-x2chWLO.gif"},{"id":"0634","n":"negative crunch","bp":"waist","tg":"abs","sm":["hip flexors"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0634-szIn2UK.gif"},{"id":"1495","n":"oblique crunch v. 2","bp":"waist","tg":"abs","sm":["obliques"],"st":["Lie on your back with your knees bent and feet flat on the ground.","Place your hands behind your head or cross them over your chest.","Engage your abs and lift your shoulder blades off the ground, rotating your torso to one side.","Pause for a moment, then lower your shoulder blades back down to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."],"gif":"1495-cJgSTmh.gif"},{"id":"0635","n":"oblique crunches floor","bp":"waist","tg":"abs","sm":["obliques"],"st":["Lie on your back with your knees bent and feet flat on the floor.","Place your hands behind your head or cross them over your chest.","Engage your abs and lift your shoulder blades off the floor, rotating your torso to one side.","Pause for a moment, then lower your shoulder blades back down to the floor.","Repeat on the other side, alternating sides with each repetition."],"gif":"0635-QUDd8WS.gif"},{"id":"1355","n":"one arm against wall","bp":"back","tg":"lats","sm":["shoulders","triceps"],"st":["Stand facing a wall with your feet shoulder-width apart.","Extend one arm straight out in front of you and place your palm against the wall.","Engage your core and lean your body forward, keeping your arm straight and your back flat.","Slowly push against the wall with your palm, activating your lat muscles.","Hold the position for a few seconds, then release and repeat with the other arm."],"gif":"1355-ZZTGMKh.gif"},{"id":"0638","n":"one arm chin-up","bp":"back","tg":"lats","sm":["biceps","forearms"],"st":["Stand facing a pull-up bar with your feet shoulder-width apart.","Reach up and grab the bar with an underhand grip, with one hand gripping the bar and the other hand holding your wrist for support.","Hang from the bar with your arm fully extended, keeping your body straight and your core engaged.","Pull yourself up towards the bar by bending your elbow and squeezing your back muscles.","Continue pulling until your chin is above the bar, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions, then switch arms and repeat."],"gif":"0638-HjdqmZa.gif"},{"id":"0639","n":"one arm dip","bp":"upper arms","tg":"triceps","sm":["chest","shoulders"],"st":["Stand facing away from a bench or chair, with your feet shoulder-width apart.","Place one hand on the bench or chair behind you, fingers pointing towards your body.","Extend your legs out in front of you, keeping your heels on the ground.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench or chair.","Pause for a moment at the bottom, then push through your palms to straighten your arms and return to the starting position.","Repeat for the desired number of repetitions, then switch sides and repeat with the other arm."],"gif":"0639-FAoIFMw.gif"},{"id":"1773","n":"one arm towel row","bp":"back","tg":"upper back","sm":["biceps","forearms"],"st":["Stand with your feet shoulder-width apart, knees slightly bent, and hold a towel with one hand.","Bend forward at the waist, keeping your back straight and your core engaged.","Extend your arm fully, allowing the towel to hang in front of you.","Pull the towel towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the towel back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"gif":"1773-bKWbrTA.gif"},{"id":"1386","n":"one leg donkey calf raise","bp":"lower legs","tg":"calves","sm":["hamstrings","glutes"],"st":["Stand with your feet shoulder-width apart, toes pointing forward.","Place your hands on a stable surface for support, such as a wall or a bar.","Lift one leg off the ground, keeping your knee slightly bent.","Raise your heel as high as possible, using your calf muscles.","Pause for a moment at the top, then slowly lower your heel back down.","Repeat for the desired number of repetitions, then switch legs."],"gif":"1386-A2upspL.gif"},{"id":"1387","n":"one leg floor calf raise","bp":"lower legs","tg":"calves","sm":["ankles","feet"],"st":["Stand with your feet hip-width apart and place your hands on a wall or sturdy object for balance.","Lift one foot off the ground and balance on the other foot.","Slowly raise your heel off the ground, lifting your body up onto the ball of your foot.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."],"gif":"1387-0jp9Rlz.gif"},{"id":"1476","n":"one leg squat","bp":"upper legs","tg":"glutes","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart.","Extend one leg forward, keeping it off the ground.","Bend your standing leg and lower your body down as if sitting back into a chair.","Keep your chest up and your back straight.","Push through your heel to return to the starting position.","Repeat with the other leg."],"gif":"1476-C31LMnP.gif"},{"id":"0642","n":"outside leg kick push-up","bp":"upper legs","tg":"glutes","sm":["quadriceps","hamstrings","calves"],"st":["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.","Lower your body towards the ground by bending your elbows, keeping your back straight and core engaged.","As you push back up, kick one leg out to the side, extending it fully and engaging your glutes.","Return your leg to the starting position and repeat the push-up, alternating legs with each repetition.","Continue alternating leg kicks and push-ups for the desired number of repetitions."],"gif":"0642-jNU1gFQ.gif"},{"id":"0643","n":"overhead triceps stretch","bp":"upper arms","tg":"triceps","sm":["shoulders"],"st":["Stand or sit upright with your feet shoulder-width apart.","Extend one arm overhead, bending at the elbow so that your hand reaches towards the opposite shoulder blade.","With your other hand, gently pull the elbow of the extended arm towards the opposite side of your head, feeling a stretch in your triceps.","Hold the stretch for 15-30 seconds, then release.","Repeat on the other side."],"gif":"0643-Z5YStHW.gif"},{"id":"3147","n":"pelvic tilt","bp":"waist","tg":"abs","sm":["lower back"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands by your sides.","Engage your abs and tilt your pelvis upward, pressing your lower back into the ground.","Hold this position for a few seconds, focusing on contracting your abs.","Release the tilt and return to the starting position.","Repeat for the desired number of repetitions."],"gif":"3147-NKJ8o6x.gif"},{"id":"1422","n":"pelvic tilt into bridge","bp":"upper legs","tg":"glutes","sm":["hamstrings","core"],"st":["Lie on your back with your knees bent and feet flat on the ground.","Place your arms by your sides with your palms facing down.","Engage your glutes and core muscles.","Tilt your pelvis upward, lifting your hips off the ground.","Hold the bridge position for a few seconds.","Slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"1422-D9qe7CM.gif"},{"id":"3662","n":"pike-to-cobra push-up","bp":"upper legs","tg":"glutes","sm":["core","shoulders","triceps"],"st":["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.","Engage your core and lift your hips up towards the ceiling, forming an inverted V shape with your body.","Lower your upper body towards the ground by bending your elbows, keeping them close to your body.","As you lower down, shift your weight forward and transition into a cobra pose by straightening your arms and lifting your chest up.","Reverse the movement by bending your elbows and lowering your chest back down towards the ground.","Push through your hands to return to the inverted V position.","Continue the movement by lowering your hips back down towards the ground, returning to the starting push-up position.","Repeat for the desired number of repetitions."],"gif":"3662-XPUDTt7.gif"},{"id":"1306","n":"plyo push up","bp":"chest","tg":"pectorals","sm":["triceps","shoulders","core"],"st":["Start in a high plank position with your hands slightly wider than shoulder-width apart.","Lower your chest towards the ground by bending your elbows, keeping your body in a straight line.","Push explosively off the ground, using your chest muscles to propel your upper body off the ground.","Land softly with your hands back in the starting position.","Repeat for the desired number of repetitions."],"gif":"1306-Snj1wSv.gif"},{"id":"1687","n":"posterior step to overhead reach","bp":"waist","tg":"abs","sm":["glutes","hamstrings","quadriceps","shoulders"],"st":["Stand with your feet hip-width apart and your arms by your sides.","Take a step back with your right foot, landing on the ball of your foot.","Bend your left knee and lower your body into a lunge position.","As you lower into the lunge, simultaneously reach your arms overhead.","Pause for a moment at the bottom of the lunge, then return to the starting position by pushing through your left heel and bringing your right foot forward.","Repeat the movement on the other side, stepping back with your left foot and bending your right knee.","Continue alternating sides for the desired number of repetitions."],"gif":"1687-ErqK3UL.gif"},{"id":"3119","n":"potty squat","bp":"waist","tg":"abs","sm":["quadriceps","glutes"],"st":["Stand with your feet shoulder-width apart, toes pointing slightly outward.","Lower your body down by bending your knees and pushing your hips back as if you were sitting on a chair.","Keep your chest up and your back straight throughout the movement.","Lower yourself until your thighs are parallel to the ground or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"gif":"3119-75Bgtjy.gif"},{"id":"3132","n":"potty squat with support","bp":"upper legs","tg":"glutes","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart, toes pointing slightly outward.","Hold onto a stable support, such as a chair or wall, for balance.","Lower your body down into a squat position by bending your knees and pushing your hips back.","Keep your chest up and your back straight throughout the movement.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"gif":"3132-b63ZzGe.gif"},{"id":"3665","n":"power point plank","bp":"waist","tg":"abs","sm":["shoulders","triceps","glutes"],"st":["Start in a high plank position with your hands directly under your shoulders and your body in a straight line from head to toe.","Engage your core and squeeze your glutes to maintain a stable position.","Lower your body down onto your forearms, one arm at a time, maintaining a straight line from head to toe.","Hold this position for the desired amount of time, keeping your core and glutes engaged.","To return to the starting position, push through your forearms and lift your body back up into a high plank position.","Repeat for the desired number of repetitions."],"gif":"3665-hCjGsRQ.gif"},{"id":"3203","n":"prisoner half sit-up (male)","bp":"waist","tg":"abs","sm":["hip flexors"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"3203-mgejmGP.gif"},{"id":"0651","n":"pull up (neutral grip)","bp":"back","tg":"lats","sm":["biceps","forearms"],"st":["Hang from a pull-up bar with a neutral grip (palms facing each other) and your arms fully extended.","Engage your core and squeeze your shoulder blades together.","Pull your body up towards the bar by bending your elbows and driving your elbows down towards your hips.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position with control.","Repeat for the desired number of repetitions."],"gif":"0651-0V2YQjW.gif"},{"id":"0652","n":"pull-up","bp":"back","tg":"lats","sm":["biceps","forearms"],"st":["Hang from a pull-up bar with your palms facing away from you and your arms fully extended.","Engage your core and squeeze your shoulder blades together.","Pull your body up towards the bar by bending your elbows and bringing your chest towards the bar.","Pause at the top of the movement, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0652-lBDjFxJ.gif"},{"id":"1689","n":"push and pull bodyweight","bp":"chest","tg":"pectorals","sm":["triceps","deltoids"],"st":["Start in a push-up position with your hands slightly wider than shoulder-width apart and your body in a straight line.","Lower your chest towards the ground by bending your elbows, keeping your body straight.","Push through your palms to extend your arms and return to the starting position.","From the push-up position, pull your chest towards the ground by bending your elbows, keeping your body straight.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."],"gif":"1689-wXvUZC8.gif"},{"id":"3638","n":"push to run","bp":"cardio","tg":"cardiovascular system","sm":["quadriceps","hamstrings","calves"],"st":["Start in a push-up position with your hands shoulder-width apart and your body in a straight line.","Lower your chest towards the ground by bending your elbows, keeping your body straight.","Push through your hands to extend your arms and return to the starting position.","Quickly bring one knee towards your chest, then quickly switch and bring the other knee towards your chest.","Continue alternating knees as fast as you can while maintaining good form.","Continue for the desired duration or number of repetitions."],"gif":"3638-PrQbjvB.gif"},{"id":"0662","n":"push-up","bp":"chest","tg":"pectorals","sm":["triceps","deltoids","core"],"st":["Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.","Engage your core and lower your body towards the ground by bending your elbows, keeping your body in a straight line.","Pause for a moment when your chest is just above the ground, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"gif":"0662-I4hDWkc.gif"},{"id":"0659","n":"push-up (wall)","bp":"chest","tg":"pectorals","sm":["triceps","deltoids"],"st":["Stand facing a wall, about arm's length away.","Place your hands on the wall at shoulder height, slightly wider than shoulder-width apart.","Step back a few feet, keeping your body straight and your feet hip-width apart.","Bend your elbows and lower your chest towards the wall, keeping your body in a straight line.","Push back up to the starting position, straightening your arms.","Repeat for the desired number of repetitions."],"gif":"0659-LEH9jxP.gif"},{"id":"0658","n":"push-up (wall) v. 2","bp":"chest","tg":"pectorals","sm":["triceps","shoulders"],"st":["Stand facing a wall, about arm's length away.","Place your hands on the wall at shoulder height, slightly wider than shoulder-width apart.","Step back with your feet, keeping them hip-width apart.","Engage your core and keep your body in a straight line from head to heels.","Bend your elbows and lower your chest towards the wall, keeping your body straight.","Pause for a moment, then push yourself back to the starting position.","Repeat for the desired number of repetitions."],"gif":"0658-NCmbLCw.gif"},{"id":"0661","n":"push-up inside leg kick","bp":"upper legs","tg":"glutes","sm":["quadriceps","hamstrings","calves","core"],"st":["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.","Lower your body towards the ground by bending your elbows, keeping your back straight and your core engaged.","As you push back up, lift one leg off the ground and kick it out to the side, keeping it straight.","Lower your leg back down and repeat the push-up, then switch to the other leg.","Continue alternating leg kicks with each push-up repetition."],"gif":"0661-0br45wL.gif"},{"id":"1467","n":"push-up on lower arms","bp":"upper arms","tg":"triceps","sm":["chest","shoulders"],"st":["Start in a plank position with your forearms on the ground and elbows directly below your shoulders.","Engage your core and keep your body in a straight line from head to toe.","Lower your chest towards the ground by bending your elbows, keeping them close to your body.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."],"gif":"1467-4Jt8QsQ.gif"},{"id":"3145","n":"push-up plus","bp":"chest","tg":"pectorals","sm":["triceps","shoulders"],"st":["Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line from head to heels.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","Once your chest is just above the ground, push through your hands to extend your arms and lift your upper body up.","At the top of the movement, protract your shoulder blades by pushing your upper back towards the ceiling.","Pause for a moment, then reverse the movement by retracting your shoulder blades and lowering your body back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"3145-pvBMLHA.gif"},{"id":"0664","n":"push-up to side plank","bp":"waist","tg":"abs","sm":["shoulders","chest","triceps"],"st":["Start in a push-up position with your hands shoulder-width apart and your body in a straight line.","Lower your body towards the ground by bending your elbows, keeping your core engaged.","Push back up to the starting position.","Shift your weight onto your left hand and rotate your body to the right, lifting your right arm towards the ceiling.","Hold the side plank position for a few seconds, then return to the starting position.","Repeat the push-up and side plank on the opposite side.","Continue alternating sides for the desired number of repetitions."],"gif":"0664-KhHJ338.gif"},{"id":"3533","n":"quads","bp":"upper legs","tg":"quads","sm":["hamstrings","glutes"],"st":["Stand with your feet shoulder-width apart.","Lower your body by bending your knees and pushing your hips back as if sitting on a chair.","Keep your chest up and your back straight.","Lower yourself until your thighs are parallel to the ground.","Push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"gif":"3533-6YUfHPL.gif"},{"id":"3201","n":"quarter sit-up","bp":"waist","tg":"abs","sm":["hip flexors"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"3201-enxnJcM.gif"},{"id":"3552","n":"quick feet v. 2","bp":"upper legs","tg":"quads","sm":["calves","hamstrings"],"st":["Stand with your feet shoulder-width apart and your arms by your sides.","Begin by rapidly moving your feet up and down, as if you were running in place.","Keep your movements quick and light, focusing on staying on the balls of your feet.","Continue for the desired duration or number of repetitions."],"gif":"3552-mweqJin.gif"},{"id":"0666","n":"raise single arm push-up","bp":"chest","tg":"pectorals","sm":["triceps","shoulders","core"],"st":["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.","Extend one arm straight out to the side, parallel to the ground.","Lower your body towards the ground by bending your elbows, keeping your back straight and core engaged.","Push back up to the starting position, using your chest muscles to lift your body.","Repeat with the other arm extended."],"gif":"0666-13TpY4H.gif"},{"id":"0668","n":"rear decline bridge","bp":"upper legs","tg":"glutes","sm":["hamstrings","lower back"],"st":["Lie on your back with your feet flat on the ground and your knees bent.","Place your arms by your sides with your palms facing down.","Engage your glutes and hamstrings, and lift your hips off the ground until your body forms a straight line from your knees to your shoulders.","Hold this position for a few seconds, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0668-UpAlold.gif"},{"id":"0669","n":"rear deltoid stretch","bp":"shoulders","tg":"delts","sm":["trapezius","rhomboids"],"st":["Stand tall with your feet shoulder-width apart.","Extend your right arm across your chest, placing your left hand on your right elbow.","Gently pull your right arm towards your left shoulder, feeling a stretch in your right shoulder.","Hold the stretch for 15-30 seconds, then release.","Repeat on the other side."],"gif":"0669-xifhB5W.gif"},{"id":"0670","n":"rear pull-up","bp":"back","tg":"lats","sm":["biceps","forearms"],"st":["Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0670-CbFSYC1.gif"},{"id":"0872","n":"reverse crunch","bp":"waist","tg":"abs","sm":["hip flexors"],"st":["Lie flat on your back with your arms extended along your sides.","Bend your knees and lift your feet off the ground, bringing your thighs perpendicular to the floor.","Contract your abs and curl your hips off the floor, bringing your knees towards your chest.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0872-nCU1Ekp.gif"},{"id":"0672","n":"reverse dip","bp":"upper arms","tg":"triceps","sm":["chest","shoulders"],"st":["Position yourself between two parallel bars with your arms fully extended and your body straight.","Lower your body by bending your elbows until your upper arms are parallel to the ground.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"gif":"0672-NZ5Qqkz.gif"},{"id":"0674","n":"reverse grip pull-up","bp":"back","tg":"lats","sm":["biceps","forearms"],"st":["Grab the pull-up bar with an underhand grip, hands shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your back muscles and pull your body up towards the bar, leading with your chest.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0674-YAk5dIw.gif"},{"id":"1423","n":"reverse hyper on flat bench","bp":"upper legs","tg":"glutes","sm":["hamstrings","lower back"],"st":["Lie face down on a flat bench with your hips at the edge and your legs hanging off the bench.","Hold onto the bench for stability.","Keeping your legs straight, raise them up towards the ceiling as high as you can.","Squeeze your glutes at the top of the movement.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"1423-OrETs32.gif"},{"id":"3663","n":"reverse plank with leg lift","bp":"waist","tg":"abs","sm":["glutes","hamstrings","shoulders"],"st":["Sit on the ground with your legs extended in front of you and your hands resting on the ground behind you, fingers pointing towards your feet.","Press through your hands and lift your hips off the ground, coming into a reverse plank position.","Engage your core and lift one leg off the ground, extending it straight up towards the ceiling.","Hold for a moment, then lower your leg back down.","Repeat with the other leg.","Continue alternating legs for the desired number of repetitions."],"gif":"3663-tFToB7l.gif"},{"id":"0677","n":"ring dips","bp":"upper arms","tg":"triceps","sm":["chest","shoulders"],"st":["Start by hanging from the rings with your arms fully extended and your body straight.","Lower your body by bending your elbows until your shoulders are below your elbows.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"gif":"0677-ezTvXcr.gif"},{"id":"2571","n":"rocking frog stretch","bp":"upper legs","tg":"glutes","sm":["hamstrings","quadriceps"],"st":["Start by kneeling on the ground with your knees hip-width apart.","Place your hands on the ground in front of you for support.","Slowly lean forward, shifting your weight onto your hands and extending your legs behind you.","Keep your back straight and engage your glutes as you push your hips back and up towards the ceiling.","Hold this position for a few seconds, feeling a stretch in your glutes.","Slowly return to the starting position by bending your knees and lowering your hips back down.","Repeat for the desired number of repetitions."],"gif":"2571-2Dk4xQV.gif"},{"id":"0678","n":"rocky pull-up pulldown","bp":"back","tg":"lats","sm":["biceps","forearms"],"st":["Stand in front of a pull-up bar with your feet shoulder-width apart.","Reach up and grab the bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your back muscles and pull your body up towards the bar, leading with your chest.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0678-cQ19bBP.gif"},{"id":"0685","n":"run","bp":"cardio","tg":"cardiovascular system","sm":["quadriceps","hamstrings","calves"],"st":["Start by standing upright with your feet hip-width apart.","Engage your core and keep your upper body relaxed.","Begin jogging in place, lifting your knees up towards your chest and landing softly on the balls of your feet.","Maintain a steady pace and continue jogging for the desired duration or distance.","Remember to breathe deeply and maintain good posture throughout the exercise."],"gif":"0685-oLrKqDH.gif"},{"id":"0684","n":"run (equipment)","bp":"cardio","tg":"cardiovascular system","sm":["quadriceps","hamstrings","calves"],"st":["Start by standing upright with your feet hip-width apart.","Engage your core and keep your upper body relaxed.","Begin jogging in place, lifting your knees up towards your chest and landing softly on the balls of your feet.","Maintain a steady pace and continue jogging for the desired duration or distance.","Remember to breathe deeply and maintain good posture throughout the exercise."],"gif":"0684-y5p0H8a.gif"},{"id":"1585","n":"runners stretch","bp":"upper legs","tg":"hamstrings","sm":["calves","quadriceps"],"st":["Stand with your feet hip-width apart.","Take a step forward with your right foot, keeping your left foot planted.","Bend your right knee and lower your body down, keeping your left leg straight.","Place your hands on your right thigh for support.","Hold the stretch for 20-30 seconds, then switch sides and repeat."],"gif":"1585-0mB6wHO.gif"},{"id":"0687","n":"russian twist","bp":"waist","tg":"abs","sm":["obliques"],"st":["Sit on the ground with your knees bent and feet flat on the floor.","Lean back slightly while keeping your back straight and your core engaged.","Hold your hands together in front of your chest or hold a weight if desired.","Lift your feet off the ground, balancing on your sit bones.","Twist your torso to the right, bringing your hands or weight towards the right side of your body.","Pause for a moment, then twist your torso to the left, bringing your hands or weight towards the left side of your body.","Continue alternating sides for the desired number of repetitions."],"gif":"0687-XVDdcoj.gif"},{"id":"3012","n":"scapula dips","bp":"back","tg":"traps","sm":["rhomboids","deltoids"],"st":["Start by standing with your feet shoulder-width apart and your arms extended in front of you.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Lower your body by bending your elbows and retracting your shoulder blades, as if you are trying to squeeze a pencil between them.","Pause for a moment at the bottom, then push through your hands to extend your elbows and return to the starting position.","Repeat for the desired number of repetitions."],"gif":"3012-7xeukSt.gif"},{"id":"3021","n":"scapula push-up","bp":"chest","tg":"serratus anterior","sm":["triceps","shoulders"],"st":["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Lower your chest towards the ground, keeping your elbows close to your body.","As you lower, squeeze your shoulder blades together and push your chest forward.","Pause for a moment at the bottom, then push back up to the starting position.","Repeat for the desired number of repetitions."],"gif":"3021-jV65tKx.gif"},{"id":"0688","n":"scapular pull-up","bp":"back","tg":"traps","sm":["biceps","rhomboids","rear deltoids"],"st":["Start by hanging from a pull-up bar with your palms facing away from you and your arms fully extended.","Retract your shoulder blades by pulling them down and back.","Engage your back muscles and pull your body up towards the bar, focusing on squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0688-uTBt1HV.gif"},{"id":"3219","n":"scissor jumps (male)","bp":"cardio","tg":"cardiovascular system","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart.","Jump off the ground and simultaneously cross your right leg in front of your left leg.","As you land, quickly switch legs, crossing your left leg in front of your right leg.","Continue alternating legs and jumping as quickly as possible.","Repeat for the desired number of repetitions."],"gif":"3219-Eh2v5Iu.gif"},{"id":"1390","n":"seated calf stretch (male)","bp":"lower legs","tg":"calves","sm":["hamstrings"],"st":["Sit on the edge of a chair or bench with your feet flat on the ground.","Extend one leg straight out in front of you, keeping your heel on the ground.","Lean forward slightly, feeling a stretch in your calf muscle.","Hold the stretch for 20-30 seconds.","Switch legs and repeat the stretch."],"gif":"1390-17bqEXD.gif"},{"id":"1424","n":"seated glute stretch","bp":"upper legs","tg":"glutes","sm":["hamstrings"],"st":["Sit on the ground with your legs extended in front of you.","Bend your right knee and cross your right ankle over your left thigh.","Place your right hand on the ground behind you for support.","With your left hand, gently press down on your right knee to deepen the stretch.","Hold the stretch for 30 seconds to 1 minute.","Switch sides and repeat."],"gif":"1424-DeDThfG.gif"},{"id":"0689","n":"seated leg raise","bp":"waist","tg":"abs","sm":["hip flexors"],"st":["Sit on a flat bench with your back straight and your feet flat on the ground.","Place your hands on the sides of the bench for support.","Keeping your legs straight, slowly raise them up in front of you until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0689-Hgs6Nl1.gif"},{"id":"0690","n":"seated lower back stretch","bp":"back","tg":"lats","sm":["glutes","hamstrings"],"st":["Sit on the edge of a chair with your feet flat on the ground.","Place your hands on your thighs or on the sides of the chair for support.","Slowly lean forward from your hips, keeping your back straight.","Feel the stretch in your lower back and hold for 20-30 seconds.","Slowly return to the starting position and repeat for the desired number of repetitions."],"gif":"0690-QFmz6ch.gif"},{"id":"2567","n":"seated piriformis stretch","bp":"upper legs","tg":"glutes","sm":["hamstrings"],"st":["Sit on the ground with your legs extended in front of you.","Bend your right knee and place your right foot on the outside of your left knee.","Place your left elbow on the outside of your right knee and gently twist your torso to the right.","Hold the stretch for 20-30 seconds, then switch sides and repeat."],"gif":"2567-QY39eBr.gif"},{"id":"0691","n":"seated side crunch (wall)","bp":"waist","tg":"abs","sm":["obliques"],"st":["Sit on the floor with your back against a wall and your legs extended in front of you.","Bend your knees and place your feet flat on the floor, hip-width apart.","Place your hands behind your head with your elbows pointing outwards.","Engage your abs and lean to one side, bringing your elbow towards your hip.","Pause for a moment, then return to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."],"gif":"0691-Y9hNPcN.gif"},{"id":"1587","n":"seated wide angle pose sequence","bp":"upper legs","tg":"hamstrings","sm":["quadriceps","calves"],"st":["Sit on the ground with your legs extended in a wide angle.","Flex your feet and engage your quadriceps.","Place your hands on the ground behind you for support.","Keeping your back straight, lean forward from your hips.","Continue leaning forward until you feel a stretch in your hamstrings.","Hold this position for a few breaths.","Slowly release the stretch and return to the starting position.","Repeat for the desired number of repetitions."],"gif":"1587-HIgYKAB.gif"},{"id":"0697","n":"self assisted inverse leg curl","bp":"upper legs","tg":"hamstrings","sm":["glutes","calves"],"st":["Lie flat on your back on a mat or bench with your legs extended.","Place your hands by your sides or under your glutes for support.","Bend your knees and lift your feet off the ground, bringing your thighs towards your chest.","Pause for a moment at the top, then slowly lower your legs back to the starting position.","Repeat for the desired number of repetitions."],"gif":"0697-GwYwElT.gif"},{"id":"1766","n":"self assisted inverse leg curl","bp":"upper legs","tg":"hamstrings","sm":["glutes","calves"],"st":["Lie face down on a leg curl machine with your legs extended and your ankles hooked under the padded lever.","Place your hands on the side handles of the machine for support.","Keeping your upper body stationary, exhale and curl your legs upward as far as possible.","Hold the contracted position for a brief pause as you squeeze your hamstrings.","Slowly lower your legs back to the starting position while inhaling.","Repeat for the desired number of repetitions."],"gif":"1766-ZSY3MsL.gif"},{"id":"0696","n":"self assisted inverse leg curl (on floor)","bp":"upper legs","tg":"hamstrings","sm":["glutes","calves"],"st":["Lie flat on your back with your legs extended and your arms by your sides.","Bend your knees and place your feet flat on the ground, hip-width apart.","Lift your hips off the ground, engaging your glutes and hamstrings.","Slowly curl your legs towards your glutes, keeping your hips lifted.","Pause for a moment at the top, then slowly extend your legs back to the starting position.","Lower your hips back down to the ground.","Repeat for the desired number of repetitions."],"gif":"0696-E4PwJqI.gif"},{"id":"3222","n":"semi squat jump (male)","bp":"cardio","tg":"cardiovascular system","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart.","Bend your knees and lower your body into a squat position.","Jump explosively, extending your hips and knees while swinging your arms for momentum.","Land softly on the balls of your feet and immediately go into the next repetition.","Repeat for the desired number of repetitions."],"gif":"3222-6FMU51h.gif"},{"id":"3656","n":"short stride run","bp":"cardio","tg":"cardiovascular system","sm":["quadriceps","hamstrings","calves"],"st":["Find an open space or a treadmill to perform the exercise.","Stand tall with your feet hip-width apart.","Start jogging in place, lifting your knees high and pumping your arms.","After a few seconds, start taking short strides forward, maintaining a quick pace.","Continue running with short strides for the desired duration or distance."],"gif":"3656-CcWEoWV.gif"},{"id":"1763","n":"shoulder grip pull-up","bp":"back","tg":"lats","sm":["biceps","forearms"],"st":["Grab the pull-up bar with a shoulder-width grip, palms facing away from you.","Hang freely with your arms fully extended.","Engage your back muscles and pull your body up towards the bar until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"1763-YtgD7Xq.gif"},{"id":"3699","n":"shoulder tap","bp":"waist","tg":"abs","sm":["shoulders","triceps"],"st":["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Engage your core and lift your right hand off the ground, reaching across to tap your left shoulder.","Place your right hand back on the ground and repeat with your left hand tapping your right shoulder.","Continue alternating shoulder taps while keeping your hips and torso stable.","Repeat for the desired number of repetitions."],"gif":"3699-yRpV5TC.gif"},{"id":"0699","n":"shoulder tap push-up","bp":"chest","tg":"pectorals","sm":["triceps","core"],"st":["Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line from head to heels.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","As you push back up, lift your right hand off the ground and tap your left shoulder.","Return your right hand to the ground and repeat the push-up, this time lifting your left hand and tapping your right shoulder.","Continue alternating shoulder taps with each push-up repetition.","Maintain a stable core and avoid excessive hip rotation throughout the exercise.","Repeat for the desired number of repetitions."],"gif":"0699-qEse6fe.gif"},{"id":"1774","n":"side bridge hip abduction","bp":"upper legs","tg":"abductors","sm":["glutes","obliques"],"st":["Lie on your side with your legs extended and stacked on top of each other.","Prop yourself up on your forearm, keeping your elbow directly below your shoulder.","Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.","While keeping your core engaged, lift your top leg as high as possible without rotating your hips.","Pause for a moment at the top, then lower your leg back down.","Repeat for the desired number of repetitions, then switch sides."],"gif":"1774-WL4EmxJ.gif"},{"id":"0705","n":"side bridge v. 2","bp":"waist","tg":"abs","sm":["obliques","glutes"],"st":["Lie on your side with your legs extended and stacked on top of each other.","Place your forearm on the ground directly below your shoulder, with your elbow bent at a 90-degree angle.","Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.","Hold this position for the desired amount of time.","Lower your hips back down to the starting position.","Repeat on the other side."],"gif":"0705-RKjH6Lt.gif"},{"id":"0709","n":"side hip (on parallel bars)","bp":"waist","tg":"abs","sm":["obliques","hip flexors"],"st":["Stand between two parallel bars with your feet shoulder-width apart.","Place your hands on the bars and lift your body off the ground, supporting your weight on your arms.","Engage your abs and slowly lift your legs to the side, keeping them straight.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0709-jTkSc6o.gif"},{"id":"0710","n":"side hip abduction","bp":"upper legs","tg":"abductors","sm":["glutes","quadriceps"],"st":["Stand with your feet shoulder-width apart and your hands on your hips.","Shift your weight to one leg and lift the opposite leg out to the side, keeping it straight.","Pause for a moment at the top, then slowly lower your leg back down to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."],"gif":"0710-7WaDzyL.gif"},{"id":"1358","n":"side lying floor stretch","bp":"back","tg":"lats","sm":["obliques","glutes"],"st":["Lie on your side with your legs straight and your bottom arm extended straight overhead.","Bend your top knee and place your foot on the ground in front of your bottom leg.","Reach your top arm over your head and grab onto something stable, like a wall or a piece of furniture.","Slowly lift your bottom leg off the ground, keeping it straight, until you feel a stretch in your side.","Hold the stretch for 20-30 seconds, then slowly lower your leg back down.","Repeat on the other side."],"gif":"1358-jDOKRM5.gif"},{"id":"3667","n":"side lying hip adduction (male)","bp":"upper legs","tg":"adductors","sm":["glutes","hamstrings"],"st":["Lie on your side with your legs straight and stacked on top of each other.","Place your bottom arm under your head for support.","Engage your adductors and lift your top leg as high as possible without rotating your hips or leaning backward.","Pause for a moment at the top, then slowly lower your leg back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"gif":"3667-c8f5cSY.gif"},{"id":"1775","n":"side plank hip adduction","bp":"upper legs","tg":"adductors","sm":["obliques","glutes"],"st":["Start by lying on your side with your legs extended and stacked on top of each other.","Prop yourself up on your forearm, keeping your elbow directly below your shoulder.","Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.","While maintaining the side plank position, lift your top leg towards the ceiling, keeping it straight.","Slowly lower your leg back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"gif":"1775-VO2qeJg.gif"},{"id":"0716","n":"side push neck stretch","bp":"neck","tg":"levator scapulae","sm":["trapezius","sternocleidomastoid"],"st":["Stand or sit up straight with your shoulders relaxed.","Tilt your head to the right, bringing your right ear towards your right shoulder.","Place your right hand on the left side of your head and gently apply pressure to increase the stretch.","Hold the stretch for 15-30 seconds.","Repeat on the other side, tilting your head to the left and applying pressure with your left hand.","Repeat the stretch 2-3 times on each side."],"gif":"0716-oQRJYkC.gif"},{"id":"0717","n":"side push-up","bp":"upper arms","tg":"triceps","sm":["shoulders","chest","core"],"st":["Start by lying on your side with your legs extended and stacked on top of each other.","Place your bottom hand on the ground directly under your shoulder, fingers pointing forward.","Press through your bottom hand to lift your body off the ground, keeping your legs straight and your core engaged.","Extend your top arm straight up towards the ceiling, creating a straight line from your head to your heels.","Lower your body back down to the starting position with control.","Repeat for the desired number of repetitions, then switch sides."],"gif":"0717-wpbD28t.gif"},{"id":"0721","n":"side wrist pull stretch","bp":"lower arms","tg":"forearms","sm":["wrists","hands"],"st":["Stand with your feet shoulder-width apart and your arms extended in front of you.","Extend your right arm out to the side, parallel to the ground, with your palm facing down.","With your left hand, grab your right hand and gently pull it towards your body, feeling a stretch in your right forearm.","Hold the stretch for 15-30 seconds, then release.","Repeat on the other side."],"gif":"0721-UtmIqcI.gif"},{"id":"0720","n":"side-to-side chin","bp":"back","tg":"lats","sm":["biceps","forearms"],"st":["Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body relaxed.","Pull yourself up by bending your elbows and bringing your chin towards the bar, while keeping your body straight.","Once your chin is above the bar, lower yourself back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0720-isAAZWA.gif"},{"id":"3213","n":"side-to-side toe touch (male)","bp":"waist","tg":"abs","sm":["obliques","hip flexors"],"st":["Stand with your feet shoulder-width apart and your arms extended to the sides.","Bend at the waist to the right, reaching your right hand towards your right foot while keeping your left hand extended to the side.","Return to the starting position and then bend at the waist to the left, reaching your left hand towards your left foot while keeping your right hand extended to the side.","Repeat the side-to-side bending motion for the desired number of repetitions."],"gif":"3213-WCAvOfC.gif"},{"id":"0725","n":"single arm push-up","bp":"chest","tg":"pectorals","sm":["triceps","shoulders","core"],"st":["Start in a push-up position with your hands shoulder-width apart and one hand placed slightly wider than the other.","Engage your core and lower your body towards the ground by bending your elbows, keeping your back straight.","As you lower yourself, shift your weight to one side and lift the opposite arm off the ground, extending it straight out to the side.","Push through your chest and triceps to raise your body back up to the starting position, while simultaneously lowering your extended arm back to the ground.","Repeat the movement, alternating the arm you extend with each repetition."],"gif":"0725-MUic5zN.gif"},{"id":"3645","n":"single leg bridge with outstretched leg","bp":"upper legs","tg":"glutes","sm":["hamstrings","quadriceps"],"st":["Lie on your back with your knees bent and feet flat on the ground.","Extend one leg straight out in front of you.","Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.","Hold for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions, then switch legs."],"gif":"3645-rmEukuS.gif"},{"id":"0730","n":"single leg platform slide","bp":"upper legs","tg":"hamstrings","sm":["glutes","quadriceps"],"st":["Start by standing with one foot on a platform or slide board.","Bend your knee slightly and slide the foot on the platform backward, extending your leg.","Keep your core engaged and maintain a straight posture throughout the movement.","Slowly return to the starting position by sliding your foot back to the initial position.","Repeat the movement for the desired number of repetitions, then switch legs."],"gif":"0730-LNE3wfo.gif"},{"id":"1759","n":"single leg squat (pistol) male","bp":"upper legs","tg":"glutes","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart and arms extended in front of you.","Lift your right foot off the ground and extend it forward.","Slowly lower your body down by bending your left knee and pushing your hips back.","Keep your chest up and your back straight as you lower yourself down.","Lower until your left thigh is parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your left heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."],"gif":"1759-nqs5HGV.gif"},{"id":"1489","n":"sissy squat","bp":"upper legs","tg":"quads","sm":["calves","glutes"],"st":["Stand with your feet shoulder-width apart and your toes pointing slightly outward.","Hold onto a stable object for balance if needed.","Slowly lower your body by bending your knees and leaning back, keeping your torso upright.","Continue lowering until your thighs are parallel to the ground or as far as you can comfortably go.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"gif":"1489-xdYPUtE.gif"},{"id":"0735","n":"sit-up v. 2","bp":"waist","tg":"abs","sm":["hip flexors"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0735-Bn6TXyO.gif"},{"id":"3679","n":"sit-up with arms on chest","bp":"waist","tg":"abs","sm":["hip flexors"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Cross your arms over your chest.","Engaging your abs, lift your upper body off the ground towards your knees.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"3679-6ZCiYWQ.gif"},{"id":"3361","n":"skater hops","bp":"cardio","tg":"cardiovascular system","sm":["quadriceps","hamstrings","glutes","calves"],"st":["Stand with your feet shoulder-width apart.","Bend your knees slightly and jump to the right, landing on your right foot.","As you land, swing your left leg behind your right leg and tap the ground with your left toes.","Immediately jump to the left, landing on your left foot.","As you land, swing your right leg behind your left leg and tap the ground with your right toes.","Continue alternating sides, jumping and tapping the ground with each leg.","Repeat for the desired number of repetitions."],"gif":"3361-zfNHMN9.gif"},{"id":"3671","n":"ski step","bp":"cardio","tg":"cardiovascular system","sm":["quadriceps","hamstrings","glutes","calves"],"st":["Stand with your feet shoulder-width apart.","Bend your knees slightly and keep your back straight.","Jump to the right, landing on your right foot while swinging your left leg behind your right leg.","Immediately jump to the left, landing on your left foot while swinging your right leg behind your left leg.","Continue alternating jumps from side to side, mimicking a skiing motion.","Repeat for the desired number of repetitions."],"gif":"3671-5MRH8H2.gif"},{"id":"3304","n":"skin the cat","bp":"back","tg":"upper back","sm":["shoulders","core"],"st":["Start by hanging from a bar with your arms fully extended and your body relaxed.","Engage your core and lift your legs up, bringing your knees towards your chest.","Continue to lift your legs up and over your head, allowing your body to pass through the arms.","Once your legs are fully extended over your head, begin to lower them back down towards the starting position.","As you lower your legs, allow your body to pass back through the arms until you are hanging with your arms fully extended again.","Repeat for the desired number of repetitions."],"gif":"3304-MSfvriJ.gif"},{"id":"1362","n":"sphinx","bp":"back","tg":"spine","sm":["glutes","hamstrings"],"st":["Lie face down on the ground with your forearms flat on the floor, elbows directly under your shoulders.","Engage your core and lift your chest off the ground, keeping your forearms and toes on the floor.","Hold this position for a few seconds, making sure to keep your neck in a neutral position.","Slowly lower your chest back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"1362-DIVyqrU.gif"},{"id":"0778","n":"spider crawl push up","bp":"upper legs","tg":"glutes","sm":["core","chest","shoulders"],"st":["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.","Bring your right knee towards your right elbow, keeping it off the ground.","As you bring your right knee back, simultaneously lower your body towards the ground by bending your elbows.","Push back up to the starting position and repeat with your left knee towards your left elbow.","Continue alternating sides for the desired number of repetitions."],"gif":"0778-P9GFBME.gif"},{"id":"1363","n":"spine stretch","bp":"back","tg":"spine","sm":["hamstrings","glutes"],"st":["Sit on the ground with your legs extended in front of you.","Place your hands on the ground behind you, fingers pointing towards your body.","Engage your core and slowly lean back, keeping your back straight.","Continue leaning back until you feel a stretch in your spine.","Hold the stretch for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"gif":"1363-JbC2iaV.gif"},{"id":"2329","n":"spine twist","bp":"waist","tg":"abs","sm":["obliques","lower back"],"st":["Sit on the ground with your legs extended in front of you.","Bend your knees and place your feet flat on the ground, hip-width apart.","Place your hands behind your head with your elbows pointing outwards.","Engage your abs and slowly twist your torso to the right, bringing your right elbow towards your left knee.","Pause for a moment at the end of the twist, then slowly return to the starting position.","Repeat the twist to the left side, bringing your left elbow towards your right knee.","Continue alternating sides for the desired number of repetitions."],"gif":"2329-2jl9K55.gif"},{"id":"2368","n":"split squats","bp":"upper legs","tg":"quads","sm":["glutes","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart.","Take a step forward with one foot and place it about two feet in front of the other foot.","Lower your body by bending your knees and hips, keeping your back straight.","Continue lowering until your front thigh is parallel to the ground, and your back knee is hovering just above the ground.","Pause for a moment, then push through your front heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."],"gif":"2368-9E25EOx.gif"},{"id":"1685","n":"squat to overhead reach","bp":"upper legs","tg":"quads","sm":["glutes","hamstrings","core"],"st":["Stand with your feet shoulder-width apart and toes slightly turned out.","Lower your body down into a squat position by bending your knees and pushing your hips back.","As you come up from the squat, extend your arms overhead, reaching towards the ceiling.","Return to the starting position by lowering your arms and bending your knees to squat down again.","Repeat for the desired number of repetitions."],"gif":"1685-QChZi3x.gif"},{"id":"1686","n":"squat to overhead reach with twist","bp":"upper legs","tg":"quads","sm":["glutes","hamstrings","core"],"st":["Stand with your feet shoulder-width apart and toes slightly turned out.","Lower your body into a squat position by bending your knees and pushing your hips back.","As you come up from the squat, raise your arms overhead and twist your torso to one side.","Return to the starting position and repeat the squat, this time twisting your torso to the opposite side.","Continue alternating sides with each squat repetition."],"gif":"1686-5BZHW9s.gif"},{"id":"3291","n":"stalder press","bp":"upper arms","tg":"triceps","sm":["shoulders","core"],"st":["Start by standing with your feet shoulder-width apart and your arms extended overhead.","Bend your knees slightly and engage your core.","Lower your body down into a squat position while keeping your arms extended overhead.","As you squat down, press your arms down towards the ground, engaging your triceps.","Pause for a moment at the bottom of the squat, then push through your heels to stand back up while simultaneously raising your arms back overhead.","Repeat for the desired number of repetitions."],"gif":"3291-zd4P4B2.gif"},{"id":"3669","n":"standing archer","bp":"back","tg":"upper back","sm":["shoulders","biceps","forearms"],"st":["Stand with your feet shoulder-width apart and your knees slightly bent.","Extend your arms straight out in front of you at shoulder height, parallel to the ground.","Rotate your torso to the right, keeping your arms extended and your back straight.","As you rotate, extend your right arm forward and your left arm back, mimicking the motion of drawing a bowstring.","Hold the position for a moment, then return to the starting position.","Repeat the motion, this time rotating your torso to the left and extending your left arm forward and your right arm back.","Continue alternating sides for the desired number of repetitions."],"gif":"3669-JF8AkMX.gif"},{"id":"1490","n":"standing calf raise (on a staircase)","bp":"lower legs","tg":"calves","sm":["ankles","feet"],"st":["Stand on the edge of a step or a sturdy platform with your heels hanging off and your toes on the step.","Hold onto a railing or wall for balance if needed.","Slowly raise your heels as high as possible, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"1490-6HmFgmx.gif"},{"id":"1397","n":"standing calves","bp":"lower legs","tg":"calves","sm":["hamstrings","glutes"],"st":["Stand with your feet shoulder-width apart, toes pointing forward.","Raise your heels off the ground as high as possible, standing on your toes.","Hold the position for a moment, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"1397-XIHEoCG.gif"},{"id":"1398","n":"standing calves calf stretch","bp":"lower legs","tg":"calves","sm":["hamstrings","glutes"],"st":["Stand facing a wall or sturdy object, about an arm's length away.","Place your hands on the wall or object at shoulder height.","Step back with one foot, keeping your heel flat on the ground.","Bend your front knee slightly and lean forward, keeping your back leg straight.","You should feel a stretch in your calf muscle.","Hold the stretch for 20-30 seconds.","Repeat on the other leg."],"gif":"1398-qOKcgVP.gif"},{"id":"0794","n":"standing lateral stretch","bp":"back","tg":"lats","sm":["shoulders","obliques"],"st":["Stand with your feet shoulder-width apart and your knees slightly bent.","Extend your arms straight out to the sides, parallel to the ground.","Slowly lean your upper body to one side, feeling a stretch in your side and lats.","Hold the stretch for 15-30 seconds.","Return to the starting position and repeat on the other side.","Repeat for the desired number of repetitions."],"gif":"0794-1jXLYEw.gif"},{"id":"1364","n":"standing pelvic tilt","bp":"back","tg":"spine","sm":["abdominals"],"st":["Stand with your feet shoulder-width apart and your knees slightly bent.","Place your hands on your hips or let them hang by your sides.","Engage your core muscles and tilt your pelvis forward, pushing your lower back towards the wall behind you.","Hold the position for a few seconds, then release and return to the starting position.","Repeat for the desired number of repetitions."],"gif":"1364-cuKYxhu.gif"},{"id":"0795","n":"standing single leg curl","bp":"upper legs","tg":"hamstrings","sm":["glutes"],"st":["Stand with your feet hip-width apart and your hands on your hips.","Shift your weight onto your left leg and lift your right foot off the ground, bending your knee.","Slowly curl your right heel towards your glutes, squeezing your hamstring.","Pause for a moment at the top, then slowly lower your right foot back down to the starting position.","Repeat for the desired number of repetitions, then switch legs."],"gif":"0795-C5jncD2.gif"},{"id":"3223","n":"star jump (male)","bp":"cardio","tg":"cardiovascular system","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart and your arms by your sides.","Bend your knees slightly and jump up explosively.","As you jump, spread your legs and extend your arms out to the sides, forming a star shape with your body.","Land softly on the balls of your feet with your knees slightly bent.","Repeat for the desired number of repetitions."],"gif":"3223-HtfCpfi.gif"},{"id":"3314","n":"straddle maltese","bp":"waist","tg":"abs","sm":["shoulders","chest"],"st":["Start by hanging from a pair of rings with your arms fully extended and your body in a straight line.","Spread your legs wide apart, forming a straddle position.","Engage your core and slowly lower your body until your arms are parallel to the ground.","Hold this position for a few seconds, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."],"gif":"3314-HfqciZF.gif"},{"id":"3298","n":"straddle planche","bp":"waist","tg":"abs","sm":["shoulders","triceps","chest"],"st":["Start in a push-up position with your hands shoulder-width apart and your feet spread wide apart.","Engage your core and slowly shift your weight forward, bringing your shoulders over your hands.","Bend your elbows and lower your body towards the ground, keeping your elbows close to your sides.","Pause for a moment at the bottom, then push through your hands to straighten your arms and lift your body back up to the starting position.","Repeat for the desired number of repetitions."],"gif":"3298-BL3GHeY.gif"},{"id":"1427","n":"straight leg outer hip abductor","bp":"upper legs","tg":"abductors","sm":["glutes","hamstrings"],"st":["Lie on your side with your legs straight and stacked on top of each other.","Place your bottom arm under your head for support.","Engage your core and lift your top leg as high as possible without rotating your hips or leaning backward.","Pause for a moment at the top, then slowly lower your leg back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"gif":"1427-mQ1tBXn.gif"},{"id":"0803","n":"superman push-up","bp":"chest","tg":"pectorals","sm":["core","shoulders"],"st":["Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.","Engage your core and lower your body towards the ground, keeping your elbows close to your sides.","As you lower your body, simultaneously lift your right arm and left leg off the ground, extending them straight out.","Pause for a moment at the top, then lower your arm and leg back down while pushing yourself back up to the starting position.","Repeat the movement, this time lifting your left arm and right leg.","Continue alternating sides for the desired number of repetitions."],"gif":"0803-4GqRrAk.gif"},{"id":"0805","n":"suspended abdominal fallout","bp":"waist","tg":"abs","sm":["obliques","hip flexors"],"st":["Attach a suspension trainer to a high anchor point and adjust the straps to waist height.","Stand facing away from the anchor point and hold the handles with your arms extended in front of you.","Lean forward at the waist, keeping your body straight and your core engaged.","Lower your body as far as you can while maintaining control and tension in your abs.","Pause for a moment at the bottom, then slowly raise your body back up to the starting position.","Repeat for the desired number of repetitions."],"gif":"0805-X3TCNEU.gif"},{"id":"0806","n":"suspended push-up","bp":"chest","tg":"pectorals","sm":["triceps","shoulders","core"],"st":["Find a suspension trainer and adjust it to an appropriate height.","Stand facing away from the anchor point and hold the handles with an overhand grip.","Walk your feet forward, leaning your body forward until your weight is supported by the suspension trainer.","Keep your body straight from head to heels, engage your core, and lower your chest towards the handles.","Push through your chest and arms to return to the starting position.","Repeat for the desired number of repetitions."],"gif":"0806-IaGQCrC.gif"},{"id":"0807","n":"suspended reverse crunch","bp":"waist","tg":"abs","sm":["hip flexors"],"st":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your knees up towards your chest, curling your pelvis towards your ribcage.","Pause for a moment at the top, then slowly lower your knees back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0807-R1WYG5D.gif"},{"id":"0808","n":"suspended row","bp":"back","tg":"upper back","sm":["biceps","shoulders"],"st":["Set up a suspension trainer at an appropriate height.","Stand facing the anchor point with your feet shoulder-width apart.","Hold the handles with an overhand grip, palms facing each other.","Lean back, keeping your body straight and your heels on the ground.","Pull your chest towards the handles, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower yourself back to the starting position.","Repeat for the desired number of repetitions."],"gif":"0808-4OaumBr.gif"},{"id":"0809","n":"suspended split squat","bp":"upper legs","tg":"quads","sm":["glutes","hamstrings","calves"],"st":["Stand facing away from a suspension trainer with your feet shoulder-width apart.","Extend one leg forward and place the top of your foot in the foot cradle of the suspension trainer.","Bend your standing leg and lower your body down into a lunge position, keeping your chest up and your knee in line with your toes.","Push through your heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."],"gif":"0809-QpXqiq8.gif"},{"id":"3433","n":"swimmer kicks v. 2 (male)","bp":"upper legs","tg":"glutes","sm":["hamstrings","quadriceps","calves"],"st":["Lie face down on a mat with your arms extended overhead.","Engage your core and lift your chest and legs off the ground simultaneously.","Kick your legs up and down in a fluttering motion, as if you were swimming.","Continue kicking for the desired number of repetitions.","Lower your chest and legs back down to the starting position."],"gif":"3433-SP3hUez.gif"},{"id":"3318","n":"swing 360","bp":"cardio","tg":"cardiovascular system","sm":["shoulders","core"],"st":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold your arms straight out in front of you, parallel to the ground.","Engage your core and swing your arms in a circular motion, rotating your torso as you do so.","Continue the circular motion, swinging your arms and rotating your torso for the desired number of repetitions.","Remember to breathe throughout the exercise."],"gif":"3318-tnaj0mT.gif"},{"id":"1753","n":"three bench dip","bp":"upper arms","tg":"triceps","sm":["chest","shoulders"],"st":["Sit on a bench with your hands gripping the edge, fingers pointing forward.","Slide your butt off the bench, supporting your weight with your hands.","Bend your elbows and lower your body until your upper arms are parallel to the ground.","Push yourself back up to the starting position.","Repeat for the desired number of repetitions."],"gif":"1753-DQ0cqkT.gif"},{"id":"0814","n":"triceps dip","bp":"upper arms","tg":"triceps","sm":["chest","shoulders"],"st":["Sit on the edge of a bench or chair with your hands gripping the edge, fingers pointing forward.","Slide your butt off the bench, supporting your weight with your hands.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."],"gif":"0814-X6C6i5Y.gif"},{"id":"0812","n":"triceps dip (bench leg)","bp":"upper arms","tg":"triceps","sm":["chest","shoulders"],"st":["Sit on the edge of a bench with your hands gripping the edge, fingers pointing forward.","Walk your feet forward, sliding your butt off the bench, and straighten your arms.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Push through your palms to straighten your arms and return to the starting position.","Repeat for the desired number of repetitions."],"gif":"0812-VuoerH0.gif"},{"id":"0813","n":"triceps dip (between benches)","bp":"upper arms","tg":"triceps","sm":["chest","shoulders"],"st":["Sit on a bench with your hands gripping the edge of the bench, fingers pointing forward.","Slide your butt off the bench, supporting your weight with your hands.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."],"gif":"0813-Wgbn9qo.gif"},{"id":"0815","n":"triceps dips floor","bp":"upper arms","tg":"triceps","sm":["chest","shoulders"],"st":["Sit on the edge of a chair or bench with your hands next to your hips, fingers pointing forward.","Slide your butt off the front of the chair with your legs extended in front of you.","Straighten your arms, keeping a little bend in your elbows to keep tension on your triceps and off your elbow joints.","Slowly bend your elbows to lower your body toward the floor until your elbows are at about a 90-degree angle.","Once you reach the bottom of the movement, press down into the chair to straighten your elbows, returning to the starting position.","Repeat for the desired number of repetitions."],"gif":"0815-7aVz15j.gif"},{"id":"0816","n":"triceps press","bp":"upper arms","tg":"triceps","sm":["shoulders"],"st":["Stand with your feet shoulder-width apart and your knees slightly bent.","Extend your arms straight out in front of you, parallel to the ground.","Bend your elbows and lower your body towards the ground, keeping your upper arms close to your sides.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."],"gif":"0816-fSrPP6B.gif"},{"id":"0817","n":"triceps stretch","bp":"upper arms","tg":"triceps","sm":["shoulders"],"st":["Stand or sit upright with your back straight.","Extend one arm overhead, bending it at the elbow.","Place your opposite hand on the bent elbow and gently pull it towards your head.","Hold the stretch for 15-30 seconds, feeling a gentle stretch in your triceps.","Release the stretch and repeat on the other arm."],"gif":"0817-uOV3Itw.gif"},{"id":"0871","n":"tuck crunch","bp":"waist","tg":"abs","sm":["hip flexors"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, lift your shoulder blades off the ground and bring your knees towards your chest, simultaneously curling your upper body towards your knees.","Pause for a moment at the top, then slowly lower your shoulder blades and extend your legs back to the starting position.","Repeat for the desired number of repetitions."],"gif":"0871-BMMolZ3.gif"},{"id":"1466","n":"twist hip lift","bp":"upper legs","tg":"glutes","sm":["obliques","hamstrings"],"st":["Lie on your back with your knees bent and feet flat on the ground.","Place your hands by your sides for support.","Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.","While keeping your hips lifted, twist your lower body to the right side, bringing your knees towards the ground.","Return to the starting position and repeat the twist to the left side.","Continue alternating twists for the desired number of repetitions."],"gif":"1466-AX1kB0o.gif"},{"id":"2802","n":"twisted leg raise","bp":"waist","tg":"abs","sm":["obliques","hip flexors"],"st":["Lie flat on your back with your legs extended and your arms by your sides.","Place your hands under your glutes for support.","Engage your abs and lift both legs off the ground, keeping them straight.","As you lift your legs, twist your hips to one side, bringing your legs towards your opposite shoulder.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat the movement, this time twisting your hips to the other side.","Continue alternating sides for the desired number of repetitions."],"gif":"2802-C0eCeEt.gif"},{"id":"2801","n":"twisted leg raise (female)","bp":"waist","tg":"abs","sm":["obliques","hip flexors"],"st":["Lie flat on your back with your legs extended and your arms by your sides.","Bend your knees and lift your legs off the ground, bringing them towards your chest.","As you lift your legs, twist your hips to one side, bringing your knees towards your opposite shoulder.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat the movement, this time twisting your hips to the other side.","Continue alternating sides for the desired number of repetitions."],"gif":"2801-yT9tk17.gif"},{"id":"3231","n":"two toe touch (male)","bp":"back","tg":"spine","sm":["hamstrings","glutes"],"st":["Stand with your feet shoulder-width apart and your arms extended out to the sides.","Bend forward at the waist, keeping your back straight and your knees slightly bent.","Reach down towards your toes with both hands, keeping your legs straight.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"gif":"3231-p195zsJ.gif"},{"id":"1365","n":"upper back stretch","bp":"back","tg":"upper back","sm":["shoulders"],"st":["Stand up straight with your feet shoulder-width apart.","Extend your arms straight in front of you, parallel to the ground.","Interlace your fingers and rotate your palms away from your body.","Slowly raise your arms overhead, keeping them straight and parallel to each other.","As you raise your arms, squeeze your shoulder blades together.","Hold the stretch for 15-30 seconds, then release and repeat."],"gif":"1365-GSDioYu.gif"},{"id":"1366","n":"upward facing dog","bp":"back","tg":"spine","sm":["shoulders","chest"],"st":["Lie face down on the floor with your legs extended behind you.","Place your hands on the floor next to your lower ribs, fingers pointing forward.","Press your hands firmly into the floor and straighten your arms, lifting your torso and thighs off the ground.","Roll your shoulders back and down, opening your chest and lifting your gaze towards the ceiling.","Hold this position for a few breaths, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"1366-01qpYSe.gif"},{"id":"3420","n":"v-sit on floor","bp":"waist","tg":"abs","sm":["hip flexors"],"st":["Sit on the floor with your legs extended in front of you.","Lean back slightly and lift your legs off the ground, keeping them straight.","Simultaneously, lift your upper body off the ground and reach your arms towards your legs.","Hold this position for a few seconds, then slowly lower your upper body and legs back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"3420-ZuXu4Eq.gif"},{"id":"0826","n":"vertical leg raise (on parallel bars)","bp":"waist","tg":"abs","sm":["hip flexors"],"st":["Hang from the parallel bars with your arms fully extended and your body straight.","Engage your core and lift your legs up in front of you, keeping them straight.","Continue lifting until your legs are parallel to the ground or slightly higher.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"0826-ZNgOYQU.gif"},{"id":"3655","n":"walking high knees lunge","bp":"cardio","tg":"cardiovascular system","sm":["quadriceps","hamstrings","glutes","calves"],"st":["Stand with your feet hip-width apart.","Lift your right knee up towards your chest as high as you can while balancing on your left leg.","Step forward with your right foot and lower your body into a lunge position, bending both knees to a 90-degree angle.","Push off with your right foot and bring your left knee up towards your chest.","Step forward with your left foot and lower your body into a lunge position.","Continue alternating legs and lunging forward, keeping your core engaged and maintaining a steady pace.","Repeat for the desired number of repetitions."],"gif":"3655-J9zIWig.gif"},{"id":"1460","n":"walking lunge","bp":"upper legs","tg":"glutes","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart.","Take a step forward with your right leg, lowering your body into a lunge position.","Keep your torso upright and your front knee aligned with your ankle.","Push off with your right foot and bring your left foot forward, stepping into a lunge position with your left leg.","Continue alternating legs and walking forward, maintaining a controlled and steady pace.","Repeat for the desired number of repetitions."],"gif":"1460-IZVHb27.gif"},{"id":"3637","n":"wheel run","bp":"cardio","tg":"cardiovascular system","sm":["quadriceps","hamstrings","calves"],"st":["Start in a plank position with your hands on the wheel and your body straight.","Engage your core and start rolling the wheel forward by extending your arms.","Continue rolling until your body is fully extended and your arms are overhead.","Reverse the movement by pulling the wheel back towards your body, using your core and arms.","Repeat for the desired number of repetitions."],"gif":"3637-km2Ljzj.gif"},{"id":"1429","n":"wide grip pull-up","bp":"back","tg":"lats","sm":["biceps","forearms"],"st":["Hang from a pull-up bar with your palms facing away from you and your hands wider than shoulder-width apart.","Engage your core and squeeze your shoulder blades together.","Pull your body up towards the bar until your chin is above the bar.","Lower your body back down to the starting position with control.","Repeat for the desired number of repetitions."],"gif":"1429-Qqi7bko.gif"},{"id":"1367","n":"wide grip rear pull-up","bp":"back","tg":"lats","sm":["biceps","forearms"],"st":["Grab the pull-up bar with a wide overhand grip, hands slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your back muscles and pull your body up towards the bar, leading with your chest.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"gif":"1367-OYFhXVD.gif"},{"id":"1311","n":"wide hand push up","bp":"chest","tg":"pectorals","sm":["triceps","shoulders"],"st":["Start in a high plank position with your hands wider than shoulder-width apart.","Keep your body in a straight line from head to toe.","Lower your chest towards the ground by bending your elbows, keeping them close to your sides.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."],"gif":"1311-JmMVpR3.gif"},{"id":"2363","n":"wide-grip chest dip on high parallel bars","bp":"chest","tg":"pectorals","sm":["triceps","shoulders"],"st":["Position yourself on the parallel bars with your arms fully extended and your body suspended in the air.","Lean forward slightly and lower your body by bending your elbows until your chest is just above the bars.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"gif":"2363-O2K9Vb5.gif"},{"id":"0858","n":"wind sprints","bp":"waist","tg":"abs","sm":["quadriceps","hamstrings","calves"],"st":["Find an open space or a track to perform the exercise.","Start by standing with your feet shoulder-width apart.","Begin running as fast as you can, pumping your arms and driving your knees up.","Continue sprinting for a specific distance or time period.","Rest and repeat for the desired number of repetitions."],"gif":"0858-Qoujh3Q.gif"},{"id":"1604","n":"world greatest stretch","bp":"upper legs","tg":"hamstrings","sm":["glutes","quadriceps","calves"],"st":["Start in a lunge position with your right foot forward and your left foot back.","Place your hands on the ground on either side of your right foot.","Lower your left knee to the ground and extend your right leg, keeping your right foot flat on the ground.","Rotate your torso to the right, reaching your right arm up towards the ceiling.","Hold this position for a few seconds, then return to the starting position.","Switch sides and repeat the stretch with your left foot forward."],"gif":"1604-DFGXwZr.gif"},{"id":"1428","n":"wrist circles","bp":"lower arms","tg":"forearms","sm":["hands","wrists"],"st":["Extend your arms straight out in front of you.","Make a fist with both hands.","Rotate your wrists in a circular motion, keeping your arms still.","Continue the wrist circles for the desired number of repetitions."],"gif":"1428-2zNKRUB.gif"}];
